const TOPICS = ["ML workflow & problem framing", "Bias-variance tradeoff & regularization", "Classification evaluation metrics", "Tree-based models", "Linear & logistic regression", "Neural network fundamentals", "Feature engineering & imbalanced data", "Regression evaluation metrics", "Cross-validation & hyperparameter tuning", "Clustering & customer segmentation", "Causal inference & experimentation", "Model interpretability & common pitfalls", "Deployment, monitoring & drift", "End-to-end applied case study"];

const LESSONS = {"ML workflow & problem framing": {"subtopics": [{"name": "Supervised vs. unsupervised learning", "md": "\nIn **supervised learning**, you have labeled historical examples - you know the outcome for past cases and want to predict it for new ones. Predicting which customers will churn next month is supervised: you have past customers, and you know who actually churned.\n\nIn **unsupervised learning**, there's no label at all - you're looking for structure in the data itself. Grouping customers into behavioral segments with no predefined \"correct\" grouping is unsupervised.\n\n## Key terms\n- **Target variable** - the specific outcome a supervised model is trained to predict (e.g. \"made zero transactions in the next 60 days\"). Every supervised problem needs one, precisely defined; unsupervised problems don't have one at all.\n- **Label** - the known, historical value of the target variable for a given past example.\n- **Feature** - an input variable used to make the prediction (e.g. tenure, recent transaction count).\n- **Training example** - one row of data: features paired with a label (supervised) or just features (unsupervised).\n- **Classification** - a supervised task where the target variable is a category (e.g. churn/no churn).\n- **Regression** - a supervised task where the target variable is a number (e.g. next month's spend).\n- **Clustering** - an unsupervised task that groups similar examples together with no predefined groups.\n"}, {"name": "Framing the problem & avoiding data leakage", "md": "\nBefore touching any modeling code, five things need to happen in order:\n\n1. Define the business problem in plain English - what decision will this model actually inform?\n2. Frame it as a specific ML task: classification, regression, or clustering.\n3. Define the target variable precisely. \"Predict churn\" is not precise; \"predict whether a customer makes zero transactions in the next 60 days\" is.\n4. Gather and engineer features, thinking about what's actually available at prediction time.\n5. Split the data, train candidate models, validate, pick one, then deploy and monitor it in production.\n\nYou typically split your labeled data three ways: the **training set** (what the model learns from), the **validation set** (used repeatedly to compare models and tune hyperparameters), and the **test set** (touched exactly once, at the very end, for an honest read on real-world performance). If you use the test set to make even one modeling decision, it quietly becomes a second validation set and your final number stops being trustworthy.\n\n**Data leakage** happens when information that wouldn't actually be available at prediction time sneaks into training - most often a feature only known *after* the outcome happens. A model trained with a leaked feature looks great in testing and then falls apart in production, because that information simply isn't there yet when a real prediction needs to be made. A classic example: including \"number of support calls about a cancellation\" as a churn feature - that number is only known once the customer has essentially already churned.\n\n## Key terms\n- **Problem framing** - translating a vague business ask into a precise, well-posed ML task (a target variable, a population, a time window).\n- **Training / validation / test set** - the three-way split of labeled data: learn from training, tune against validation, get an honest final read from test (touched once).\n- **Data leakage** - a feature or signal in training data that wouldn't genuinely be available at the moment of a real prediction, making measured performance overly optimistic.\n", "note": "The most common mistake in an ML fundamentals discussion isn't picking the wrong algorithm - it's skipping straight to model choice before nailing down what the target variable actually is and whether the features you'd use are genuinely available at the moment you'd need to make the prediction. Naming the target variable precisely and checking for leakage earns more credit than jumping straight to \"I'd use XGBoost.\""}, {"name": "Choosing model complexity for the data you have", "md": "\nModel selection is part of the workflow too, and it's not just \"pick the fanciest option.\" Two things matter most: how much labeled data you have, and how important it is to explain a prediction to a stakeholder.\n\nNeural networks typically need far more data than a few thousand rows to learn reliably, and they're harder to explain to a non-technical stakeholder who will ask why the model flagged a given customer. Simpler models - logistic regression, gradient-boosted trees - often match or beat a neural network's accuracy on small-to-medium tabular datasets, while being faster to train, easier to debug, and easier to justify.\n\n## Key terms\n- **Baseline model** - a simple, quick-to-build model used as a first reference point before trying anything more complex.\n- **Interpretability** - how easily a human can understand why a model made a specific prediction.\n"}]}, "Bias-variance tradeoff & regularization": {"subtopics": [{"name": "Bias vs. variance", "md": "\n**Bias** is error from a model that's too simple to capture the real pattern - it makes strong, often wrong, assumptions and underfits. **Variance** is error from a model that's too sensitive to the specific training data it happened to see - it fits the noise, not just the signal, and overfits.\n\nA straight line forced through clearly curved data has high bias. A wiggly curve that passes through every single training point but swings wildly on new data has high variance.\n\nAs you increase model complexity (more features, deeper trees, more parameters), bias tends to fall and variance tends to rise. Total error is roughly U-shaped across that complexity spectrum - too simple and too complex both hurt you, and the best model sits somewhere in the middle.\n\n## Key terms\n- **Bias** - error from overly simplistic assumptions; shows up as poor performance on training data itself.\n- **Variance** - error from excess sensitivity to the training sample; shows up as a large gap between training and validation performance.\n- **Underfitting** - a model too simple to capture the real pattern (high bias).\n- **Overfitting** - a model that has learned the training data's noise, not just its signal (high variance).\n", "video": {"id": "Unol0NZtuRo", "title": "Bias-Variance Trade-Off, Clearly Explained"}}, {"name": "Diagnosing bias vs. variance", "md": "\nThe fastest way to tell which problem you have is to compare training performance to validation performance:\n\n- Training and validation both poor -> high **bias** (underfitting).\n- Training excellent, validation much worse -> high **variance** (overfitting).\n- Training and validation both good and close together -> a reasonable spot.\n\nThis diagnostic matters because the fix runs in opposite directions depending on which one you have - there's no single universal fix that helps both.\n\n## Key terms\n- **Generalization** - how well a model's performance on training data carries over to new, unseen data.\n"}, {"name": "Regularization: Ridge & Lasso", "md": "\n**Regularization** adds a penalty for large coefficients directly into what the model is trying to minimize, discouraging it from leaning too hard on any one feature. It's the main lever for reducing variance.\n\n- **Ridge (L2)** shrinks all coefficients toward zero, but rarely all the way to exactly zero.\n- **Lasso (L1)** can shrink some coefficients to *exactly* zero, effectively removing those features - useful when you suspect only a handful of your features actually matter.\n\nIf a model is high-variance, increasing regularization strength (or simplifying the model) helps. If a model is high-bias, the fix runs the other way: reduce regularization strength, add more informative features, or move to a more flexible model class entirely.\n\n## Key terms\n- **Regularization** - a penalty added to a model's training objective that discourages overly large coefficients, trading a little bias for less variance.\n- **Ridge regression (L2)** - regularization that shrinks all coefficients toward zero without eliminating any entirely.\n- **Lasso regression (L1)** - regularization that can shrink some coefficients to exactly zero, a form of automatic feature selection.\n- **Hyperparameter** - a setting chosen before training (like regularization strength) rather than learned from the data itself.\n", "note": "\"Just collect more data\" is a classic interview trap. More training data reliably helps a high-variance problem (the model has less room to memorize noise), but it does essentially nothing for a high-bias problem - if your model is fundamentally too simple for the pattern, feeding it more of the same simple assumptions just gets you a more confidently wrong model, not a better one."}]}, "Classification evaluation metrics": {"subtopics": [{"name": "Confusion matrix, precision & recall", "md": "\nEvery binary classifier's predictions at a given threshold fall into four buckets, defined against the actual outcome:\n\n- **True Positive (TP)**: predicted positive, actually positive.\n- **False Positive (FP)**: predicted positive, actually negative - a false alarm.\n- **False Negative (FN)**: predicted negative, actually positive - a miss.\n- **True Negative (TN)**: predicted negative, actually negative.\n\nTake a model predicting which customers will make a repeat payment: a customer flagged as likely-to-repeat who actually does is a TP; one flagged as likely-to-repeat who never does is a FP.\n\n**Precision** = TP / (TP + FP) - of everyone you flagged as positive, what fraction actually were? **Recall** = TP / (TP + FN) - of everyone who actually was positive, what fraction did you catch? These trade off against each other, and which one matters more is a business question: if a false positive is cheap, prioritize recall; if it's expensive, prioritize precision. **F1 score** is the harmonic mean of the two, useful when you want one number balancing both.\n\n## Key terms\n- **Confusion matrix** - the TP/FP/FN/TN breakdown of a classifier's predictions at a given threshold.\n- **Precision** - TP / (TP + FP); how trustworthy a positive prediction is.\n- **Recall** - TP / (TP + FN); how completely the model catches real positives.\n- **F1 score** - the harmonic mean of precision and recall.\n", "note": "Accuracy alone is a misleading metric on imbalanced data. If only 5% of customers actually churn, a model that predicts \"never churns\" for everyone is 95% accurate and completely useless. This is exactly why precision, recall, and F1 exist - always ask about the class balance before trusting an accuracy number."}, {"name": "Computing metrics from real predictions", "md": "\nTo turn a model's predicted probability into a classification, pick a **threshold**: everything scored at or above it is predicted positive, everything below is predicted negative. A threshold of 0.5 is the common default, but it's just a choice - shifting it trades precision for recall in either direction.\n\nOnce you have predicted labels at a chosen threshold, computing TP/FP/FN/TN is direct boolean-mask arithmetic against the actual outcome column, and precision/recall/F1 follow immediately from those four counts.\n\n## Key terms\n- **Threshold** - the cutoff on a predicted probability above which a prediction is called \"positive.\"\n"}, {"name": "AUC & the rank-sum method", "md": "\nEvery metric so far depends on the threshold you chose - a different cutoff gives a different confusion matrix. **AUC** (Area Under the ROC Curve) sidesteps that: it's the probability that a randomly chosen positive example gets a higher score than a randomly chosen negative one, across *all* thresholds at once. AUC of 0.5 means the model is no better than random guessing; 1.0 means perfect separation; real production models often land around 0.75-0.90.\n\nAUC can be computed directly from ranks, without ever touching sklearn: rank every prediction score from lowest to highest (ties get the average rank), then\n\n`AUC = (sum of ranks belonging to positive examples - n_pos * (n_pos + 1) / 2) / (n_pos * n_neg)`\n\nThis works because the sum of ranks of the positive class, adjusted by the smallest-possible sum a positive class of that size could have, counts exactly how many positive/negative pairs are correctly ordered - which is precisely what AUC measures. `scipy.stats.rankdata` computes the ranks (average rank for ties) needed for this formula.\n\n## Key terms\n- **AUC (Area Under the Curve)** - the probability a random positive example outscores a random negative one; a threshold-independent summary of separability.\n- **Rank** - an example's position when all predicted scores are sorted from lowest to highest; ties share the average rank.\n", "video": {"id": "4jRBRDbJemM", "title": "ROC and AUC, Clearly Explained"}}]}, "Tree-based models": {"subtopics": [{"name": "Decision trees", "md": "\nA decision tree asks a series of yes/no questions about your features, splitting the data at each step to make the resulting groups as \"pure\" as possible (mostly one class, or a tight range of values).\n\nThey're easy to explain to a non-technical stakeholder - you can literally draw the tree and walk someone through the logic - but a single deep tree tends to overfit badly (high variance): left unconstrained, it keeps splitting until each leaf is tailored to a tiny handful of specific training rows, memorizing quirks rather than general patterns.\n\n## Key terms\n- **Decision tree** - a model that makes predictions via a sequence of feature-based yes/no splits.\n- **Purity** - how homogeneous the data in a node is after a split; trees choose splits that increase purity the most.\n", "video": {"id": "_L39rN6gz7Y", "title": "Decision and Classification Trees, Clearly Explained"}}, {"name": "Random forests & bagging", "md": "\nA random forest trains many decision trees, each on a random subset of the rows and a random subset of the features, then averages their predictions (or takes a majority vote for classification).\n\nThis is called **bagging** (bootstrap aggregating): individual trees still overfit their own random slice of the data, but their errors are different from each other and tend to cancel out when averaged, which is what makes the forest far less variance-prone than any single tree.\n\n## Key terms\n- **Random forest** - an ensemble of many decision trees, each trained on a random subset of rows and features, combined by averaging or voting.\n- **Bagging** - training many models independently on random subsets of data and combining their predictions to cancel out individual overfitting.\n", "video": {"id": "J4Wdy0Wc_xQ", "title": "StatQuest: Random Forests Part 1"}}, {"name": "Gradient boosting", "md": "\nGradient boosting (the family behind XGBoost, LightGBM) also combines many trees, but builds them *sequentially* rather than independently - each new tree is trained specifically to correct the errors the previous trees made.\n\nFor structured, tabular business data specifically, gradient-boosted ensembles are usually the strongest off-the-shelf choice, often edging out random forests on raw accuracy. That said, it's more sensitive to hyperparameters - learning rate, tree depth, number of boosting rounds - and if those aren't tuned carefully it can overfit more easily than a random forest. It's also slower to train, since each tree in the sequence depends on the errors of the ones before it and can't be built in parallel the way a forest's independent trees can.\n\n## Key terms\n- **Gradient boosting** - an ensemble that builds trees sequentially, each one correcting the errors of the trees before it.\n- **Learning rate** - how much each new tree's correction is allowed to influence the overall prediction.\n"}]}, "Linear & logistic regression": {"subtopics": [{"name": "Linear regression basics", "md": "\nLinear regression predicts a continuous number as a weighted sum of the input features, plus an intercept: `prediction = intercept + w1*x1 + w2*x2 + ...`. The model learns the weights (coefficients) that make this weighted sum fit the training data as closely as possible, measured by squared error - the sum of (actual - predicted) squared across all training rows.\n\nEach coefficient has a direct interpretation: holding every other feature constant, a coefficient of `2.5` on `tenure_months` means each additional month of tenure is associated with a 2.5-unit increase in the predicted outcome.\n\n## Key terms\n- **Linear regression** - a model that predicts a continuous target as a weighted sum of the input features plus an intercept.\n- **Coefficient (weight)** - the number a feature is multiplied by; its size and sign describe that feature's association with the target, holding other features constant.\n- **Intercept** - the predicted value when every feature is zero.\n"}, {"name": "From linear to logistic regression", "md": "\nPlain linear regression breaks down for a yes/no target like \"will this customer make a repeat payment?\" Its raw output is unbounded - it can predict a probability-like number below 0% or above 100%, which is meaningless.\n\n**Logistic regression** fixes this by passing the same weighted sum through the **sigmoid function**, `1 / (1 + e^-z)`, which squashes any number into the range (0, 1). That squashed value is interpreted as a probability, and a **threshold** (commonly 0.5) turns it into a yes/no decision - exactly the mechanism behind the `pred_score` column you've already worked with.\n\n## Key terms\n- **Logistic regression** - a model that predicts the probability of a binary outcome by passing a weighted sum of features through the sigmoid function.\n- **Sigmoid function** - the S-shaped function that maps any real number into the range (0, 1), used to turn a raw weighted sum into a probability.\n"}, {"name": "Interpreting coefficients & log loss", "md": "\nA logistic regression coefficient is a bit less direct than a linear regression one: it describes the change in **log-odds** of the outcome, not the change in probability itself, for a one-unit increase in that feature (holding others constant). A positive coefficient means the feature increases the probability of the outcome; a negative one decreases it.\n\nBecause the target is a probability rather than a raw number, logistic regression isn't trained by minimizing squared error - it's trained by minimizing **log loss** (also called cross-entropy), which heavily penalizes confident, wrong predictions. For a single example with actual label `y` and predicted probability `p`, the log loss is `-(y*log(p) + (1-y)*log(1-p))`; the model's overall log loss is the average of this across every training example.\n\n## Key terms\n- **Log-odds** - the natural logarithm of the odds of the outcome; logistic regression coefficients describe change in log-odds, not raw probability.\n- **Log loss (cross-entropy)** - the loss function logistic regression minimizes; it penalizes a confident wrong prediction (e.g. predicting 0.99 for an example that was actually 0) far more heavily than a cautious wrong one.\n"}]}, "Neural network fundamentals": {"subtopics": [{"name": "Neurons, layers & the forward pass", "md": "\nA single **neuron** computes a weighted sum of its inputs plus a bias, then passes that sum through an **activation function**. That's the entire computation - the same building block as logistic regression, just with a name change (weights, bias, activation).\n\nA **neural network** stacks many of these neurons into **layers**: an input layer (the raw features), one or more **hidden layers**, and an output layer (the final prediction). Passing an input all the way through every layer to produce a prediction is called the **forward pass**.\n\n## Key terms\n- **Neuron** - a unit that computes a weighted sum of its inputs plus a bias, then applies an activation function.\n- **Layer** - a group of neurons that all take the same inputs and feed into the same next step.\n- **Hidden layer** - any layer between the input and the output layer.\n- **Forward pass** - running an input all the way through the network's layers to produce a prediction.\n"}, {"name": "Why non-linear activation functions matter", "md": "\nThe activation function inside each neuron is what makes a network more powerful than plain logistic regression. Common choices are **sigmoid** (squashes to (0,1), used in logistic regression too) and **ReLU** (`max(0, z)`, the most common choice in hidden layers today).\n\nThe activation function has to be non-linear. If every neuron's activation were purely linear, stacking any number of layers would collapse mathematically into a single linear transformation - a 10-layer network would compute nothing a single linear regression couldn't already compute. Non-linear activations are exactly what let a deep network learn complex, curved relationships that a linear model can't.\n\n## Key terms\n- **Activation function** - the function applied to a neuron's weighted sum; must be non-linear for depth to add any modeling power.\n- **ReLU** - `max(0, z)`; the most common hidden-layer activation in modern networks.\n"}, {"name": "Training: loss and gradient descent", "md": "\nA freshly initialized network's forward pass produces essentially random predictions. Training means adjusting every weight and bias across all layers to reduce a **loss function** (like log loss for classification) computed on the training data.\n\n**Gradient descent** is the mechanism: for each weight, compute how much a tiny change in that weight would change the loss (its gradient), then nudge the weight slightly in the direction that reduces the loss. **Backpropagation** is the specific algorithm that efficiently computes those gradients for every weight in the network, layer by layer, working backward from the output. Repeating this nudge-and-recompute cycle many times over the training data is what gradually improves the network's predictions.\n\n## Key terms\n- **Loss function** - the quantity training tries to minimize (e.g. log loss for classification).\n- **Gradient descent** - repeatedly nudging each weight in the direction that reduces the loss.\n- **Backpropagation** - the algorithm that computes the gradient of the loss with respect to every weight in the network.\n"}]}, "Feature engineering & imbalanced data": {"subtopics": [{"name": "What makes a good feature", "md": "\nRaw data is rarely the best input to a model directly. **Feature engineering** is the work of constructing informative input variables from raw data - for example, turning a raw \"last transaction timestamp\" into \"days since last transaction,\" or combining several raw columns into a ratio like \"spend this month / average spend over the last 6 months\" that captures a meaningful change in behavior.\n\nGood features are informative (they actually relate to the target), available at prediction time (no leakage), and in a form the model can use - categorical values like \"country\" typically need to be encoded into numbers before most models can use them.\n\n## Key terms\n- **Feature engineering** - constructing informative input variables for a model from raw underlying data.\n- **Encoding** - converting a categorical value (like a country name) into a numeric representation a model can use.\n"}, {"name": "Why imbalanced data is a problem", "md": "\nAn **imbalanced** target variable is one where one class vastly outnumbers the other - a 1.5% fraud rate, for example. This causes two distinct problems. First, **accuracy becomes a misleading metric**: a model that predicts \"not fraud\" for every single transaction would still be 98.5% accurate while catching zero fraud. Second, and more subtly, training itself is affected: the vast majority of training examples belong to the majority class, so the loss function's overall value is dominated by getting the majority class right, giving the model little incentive to work hard on learning the rare, minority-class pattern at all.\n\n## Key terms\n- **Imbalanced data** - a target variable where one class is far more common than the other in the training data.\n"}, {"name": "Handling imbalance: resampling & class weights", "md": "\nTwo common fixes, applied only to the **training set**: **undersampling** the majority class (dropping some majority-class rows so the classes are closer to balanced) and **oversampling** the minority class (duplicating or synthetically generating more minority-class rows). An alternative that doesn't touch the data at all is **class weighting**: telling the model's loss function to penalize a mistake on the minority class more heavily than a mistake on the majority class, which has a similar rebalancing effect without discarding or duplicating any rows.\n\nWhichever fix you choose, the **validation and test sets must be left in their original, real-world proportions** - they need to reflect what the model will actually see in production, so evaluating against an artificially rebalanced test set would give a misleading performance estimate.\n\n## Key terms\n- **Undersampling** - removing rows from the majority class in training data to reduce imbalance.\n- **Oversampling** - duplicating or synthetically generating minority-class rows in training data to reduce imbalance.\n- **Class weighting** - penalizing misclassifications of the minority class more heavily in the loss function, instead of changing the data itself.\n"}]}, "Regression evaluation metrics": {"subtopics": [{"name": "MAE & RMSE", "md": "\nFor a regression model (predicting a continuous number), the two most common error metrics both start from the same idea: the error on one prediction is `actual - predicted`.\n\n**MAE (Mean Absolute Error)** is the average of the absolute value of that error across all predictions - every error contributes proportionally to its size. **RMSE (Root Mean Squared Error)** squares each error before averaging, then takes the square root at the end - because squaring makes large errors count disproportionately more, RMSE is more sensitive to a few big misses than MAE is. Both are reported in the same units as the target variable itself (dollars, days, etc.), which makes them directly interpretable.\n\n## Key terms\n- **MAE (Mean Absolute Error)** - the average absolute difference between actual and predicted values; treats every error proportionally to its size.\n- **RMSE (Root Mean Squared Error)** - the square root of the average squared error; penalizes large individual errors more heavily than MAE does.\n"}, {"name": "R-squared (coefficient of determination)", "md": "\n**R-squared (R²)** answers a different question than MAE or RMSE: instead of \"how big are the errors,\" it asks \"how much of the variation in the actual outcome does the model explain, compared to just guessing the average for everyone?\"\n\nAn R² of 1.0 means the model explains all the variation (perfect predictions). An R² of 0 means the model does no better than always predicting the training set's average value. R² *can* go negative, which means the model is actually doing worse than that naive \"always guess the average\" baseline - a genuine red flag.\n\n## Key terms\n- **R-squared (R²)** - the proportion of variance in the actual outcome explained by the model, relative to always predicting the average.\n- **Baseline (naive) model** - the simplest possible comparison point, such as always predicting the training set's average value.\n"}, {"name": "Choosing the right metric for the business", "md": "\nWhich metric to lead with is a business judgment, not just a technical one. If a few very large errors are especially costly (e.g. wildly underestimating a large refund), **RMSE**'s extra sensitivity to big misses is the right lens. If you want a metric that's robust to occasional outliers and easy to explain as \"the model is off by about $X on average,\" **MAE** communicates that directly. **R²** is most useful for comparing how much explanatory power different models or feature sets add, independent of the target's original units.\n\nA related metric worth knowing by name is **MAPE** (Mean Absolute Percentage Error), which expresses error as a percentage of the actual value - it's intuitive, but it blows up or becomes undefined when the actual value is at or near zero, so it's a poor choice whenever your target variable can be zero or very small.\n\n## Key terms\n- **MAPE (Mean Absolute Percentage Error)** - average absolute error expressed as a percentage of the actual value; unstable when actual values are near zero.\n"}]}, "Cross-validation & hyperparameter tuning": {"subtopics": [{"name": "Why a single validation split isn't enough", "md": "\nA single train/validation split has a hidden weakness: which specific rows happen to land in the validation set is random, and with a limited amount of data, that random luck can meaningfully swing the estimated performance. Run the same model against a different random split and you might see a noticeably different validation score - not because the model changed, but because the split did.\n\nThis matters most exactly when you have the least data to spare, which is often when you can least afford a noisy performance estimate.\n\n## Key terms\n- **Validation split variance** - the amount a validation performance estimate would change just from which rows happened to be randomly assigned to it.\n"}, {"name": "K-fold cross-validation", "md": "\n**K-fold cross-validation** fixes this by not relying on just one split. The training data is divided into `k` roughly equal-sized groups called **folds**. The model is trained `k` times, each time on `k-1` folds combined, with the one remaining fold held out and used for validation. Every fold gets a turn being the held-out validation set exactly once. The final reported performance is the **average** of the metric across all `k` runs.\n\nBecause every row gets used for both training and validation (just never at the same time), this gives a far more stable, reliable estimate of performance than any single split - the noise from any one lucky or unlucky split gets averaged away.\n\n## Key terms\n- **K-fold cross-validation** - splitting data into k folds, training k times with each fold held out once for validation, and averaging the resulting metric.\n- **Fold** - one of the k roughly equal partitions the training data is split into for cross-validation.\n"}, {"name": "Hyperparameter tuning & the final retrain", "md": "\nCross-validation is also the right tool for **hyperparameter tuning** - comparing different settings (like a tree's max depth, or a regularization strength) by their average cross-validated performance rather than a single split's score, since a single split could make a worse hyperparameter setting look better just by chance.\n\n**Grid search** exhaustively tries every combination of hyperparameter values you specify; **random search** instead samples a fixed number of random combinations, which often finds a similarly good setting far faster when there are many hyperparameters to search over.\n\nCritically, all of this tuning happens using cross-validation on the training data alone - the test set is never used to pick a hyperparameter setting, only to give one final, honest performance read on the model you've already fully chosen.\n\n## Key terms\n- **Hyperparameter tuning** - searching over different hyperparameter settings and comparing their cross-validated performance to choose the best one.\n- **Grid search** - trying every combination of a specified set of hyperparameter values.\n- **Random search** - sampling a fixed number of random hyperparameter combinations instead of trying every one.\n"}]}, "Clustering & customer segmentation": {"subtopics": [{"name": "Clustering as unsupervised learning", "md": "\n**Clustering** groups similar examples together with no predefined \"correct\" grouping and no labels at all - it's a purely unsupervised task. Where classification predicts a known category (churn/no churn) using labeled historical examples, clustering instead discovers structure that wasn't specified upfront, based purely on how similar or different examples are from each other.\n\nA customer segmentation task - grouping customers into behavioral tiers based on spend, frequency, and tenure, with no predefined \"correct\" set of tiers - is a classic clustering problem.\n\n## Key terms\n- **Clustering** - an unsupervised task that groups similar examples together with no predefined groups or labels.\n- **Similarity / distance** - the core idea clustering relies on: examples that are numerically \"close\" to each other (by some distance measure) are grouped together.\n"}, {"name": "K-means clustering", "md": "\n**K-means** is the most common clustering algorithm. You choose the number of clusters, `k`, upfront. The algorithm then: (1) places `k` initial **centroids** (cluster centers), (2) assigns every example to its nearest centroid, (3) recomputes each centroid as the average of the examples now assigned to it, and (4) repeats steps 2-3 until the assignments stop changing.\n\nBecause k-means assigns points based on distance, **feature scaling matters a lot**: if \"annual spend\" is measured in dollars (ranging into the thousands) and \"tenure\" is measured in months (ranging up to a few hundred), spend will dominate the distance calculation purely because of its larger numeric scale, even if tenure is actually just as meaningful for segmentation.\n\n## Key terms\n- **K-means** - a clustering algorithm that assigns points to the nearest of k centroids, then recomputes centroids, repeating until stable.\n- **Centroid** - the center point of a cluster, computed as the average of all examples currently assigned to it.\n- **Feature scaling** - rescaling features so they're on comparable numeric ranges, needed for distance-based algorithms like k-means to weigh each feature fairly.\n", "video": {"id": "4b5d3muPQmA", "title": "StatQuest: K-means clustering"}}, {"name": "Choosing k & evaluating clusters", "md": "\nK-means requires choosing `k` upfront, and picking it well matters. The **elbow method** plots the within-cluster sum of squares (WCSS - how tightly packed points are around their centroid) against different values of `k`; WCSS always keeps decreasing as `k` increases (it hits zero once every point is its own cluster), so the goal isn't the lowest WCSS overall, but the point where adding another cluster stops giving a meaningfully large improvement - the \"elbow\" in the curve.\n\nThe **silhouette score** offers a second, complementary check: it measures how well-separated clusters actually are, rather than just how tight each one is internally. But ultimately, a segmentation's real test is whether the resulting groups are **actionable** for the business - do they suggest genuinely different treatments or strategies? A statistically \"optimal\" k that produces segments no one can act on differently isn't actually useful.\n\n## Key terms\n- **Elbow method** - plotting within-cluster sum of squares against k and looking for the point of diminishing returns, rather than picking the lowest WCSS outright.\n- **Within-cluster sum of squares (WCSS)** - a measure of how tightly points are packed around their cluster's centroid; always decreases as k increases.\n- **Silhouette score** - a metric measuring how well-separated clusters are from each other, complementing WCSS.\n"}]}, "Causal inference & experimentation": {"subtopics": [{"name": "Correlation vs. causation & confounders", "md": "\nTwo variables moving together (correlation) doesn't mean one causes the other. A **confounder** is a third variable that influences both, creating a correlation between them that isn't causal at all.\n\nFor example: customers who use a company's mobile app have higher retention than those who don't. It's tempting to conclude the app *causes* retention - but a plausible confounder is that customers who were already more engaged and loyal *before* installing the app are also simply more likely to install it in the first place. The app didn't necessarily cause anything; pre-existing engagement drove both the app adoption and the retention.\n\n## Key terms\n- **Correlation** - two variables tending to move together, with no claim about one causing the other.\n- **Causation** - one variable's change directly producing a change in another.\n- **Confounder** - a third variable that influences both variables of interest, creating a misleading correlation between them.\n"}, {"name": "A/B testing (randomized experiments)", "md": "\n**A/B testing** (a randomized controlled experiment) is the gold standard for establishing causation. Customers are randomly assigned to a **treatment group** (gets the new feature, offer, or program) or a **control group** (doesn't), and the outcome is compared between the two groups afterward.\n\nRandomization is what makes causal claims valid: because assignment to treatment or control is random, the two groups should be statistically similar on *every* other characteristic - engagement, tenure, spend habits, everything - on average, before the experiment even starts. Any confounders that might otherwise muddy the comparison get evenly spread across both groups by the randomization itself, so any difference in outcome afterward can be attributed to the treatment.\n\n## Key terms\n- **A/B test (randomized controlled experiment)** - randomly assigning subjects to treatment or control groups to measure a causal effect.\n- **Treatment group** - the group that receives the intervention being tested.\n- **Control group** - the group that does not receive the intervention, used as the causal baseline.\n"}, {"name": "When you can't randomize: quasi-experimental methods", "md": "\nSometimes randomization isn't feasible - a program gets rolled out to everyone at once, or a policy change applies to an entire market. Two common **quasi-experimental** methods estimate a causal effect anyway:\n\n**Difference-in-differences** compares the *change* in outcome (before vs. after) for the treated group against the change over the same period for a comparable untreated group, isolating the treatment's effect from any trend both groups would have experienced anyway. Its key assumption is **parallel trends**: absent the treatment, the two groups would have moved similarly over time.\n\n**Propensity score matching** instead constructs a synthetic comparison group after the fact, by pairing each treated customer with an untreated customer who had a very similar predicted probability of receiving the treatment in the first place (based on their observed characteristics), then comparing outcomes between the matched pairs.\n\n## Key terms\n- **Quasi-experimental method** - a technique for estimating a causal effect when true randomization isn't possible.\n- **Difference-in-differences** - comparing the before/after change for a treated group against the before/after change for a comparable untreated group.\n- **Parallel trends assumption** - the assumption underlying difference-in-differences: absent treatment, the treated and comparison groups would have trended similarly.\n- **Propensity score matching** - pairing treated and untreated subjects with similar estimated likelihoods of receiving treatment, then comparing their outcomes.\n", "video": {"id": "ACVyPp1Fy6Y", "title": "An intuitive introduction to Propensity Score Matching"}}]}, "Model interpretability & common pitfalls": {"subtopics": [{"name": "Why interpretability matters", "md": "\n**Interpretability** - being able to explain why a model made a specific prediction - matters for reasons beyond pure accuracy. In regulated domains like credit or lending decisions, companies are often legally required to be able to explain an adverse decision to the affected customer. Interpretability also helps you debug a model (is it relying on sensible signal, or something spurious?) and helps stakeholders trust and adopt a model's recommendations in the first place.\n\n## Key terms\n- **Interpretability** - the degree to which a human can understand why a model produced a given prediction.\n"}, {"name": "Global vs. local interpretability", "md": "\n**Global interpretability** describes the model's behavior overall - typically a ranking of **feature importance** across the whole model, answering \"which features matter most, in general?\" **Local interpretability** instead explains one single prediction - answering \"why did the model flag *this specific* customer?\" - which is what's actually needed to satisfy a specific customer's or regulator's question about one decision.\n\nYou'd reach for global feature importance when validating the model's overall behavior makes business sense (a sanity check during development), and local, per-prediction explanations when you need to justify or act on one individual outcome.\n\n## Key terms\n- **Global interpretability** - understanding a model's behavior overall, typically via feature importance across the whole model.\n- **Local interpretability** - explaining a single, individual prediction.\n- **Feature importance** - a ranking of how much each feature contributes to a model's predictions overall.\n"}, {"name": "Common pitfalls: proxies, correlated features & sanity checks", "md": "\nA model's feature importance ranking can be misleading in a few specific ways. When two features are highly **correlated**, the model can split credit for the same underlying signal between them, making each look less important individually than the combined signal actually is.\n\nA more serious pitfall: a model can learn a strong pattern through a **proxy** for a protected characteristic, even when that characteristic is never used directly. A classic example is zip code standing in for race, due to historical correlations between geography and demographics - the model never \"sees\" race, but can still produce outcomes that disproportionately disadvantage a demographic group.\n\nWhenever a feature's importance is surprising, the right response is to sanity-check it against domain knowledge - does it actually make business sense that this feature matters this much? - and specifically to investigate whether a suspicious feature might be acting as a proxy, checking its correlation with demographic data and auditing model outcomes across groups for disparate impact.\n\n## Key terms\n- **Correlated features** - features that carry overlapping information, which can split or distort feature-importance rankings.\n- **Proxy variable** - a feature that isn't a protected characteristic itself but is correlated with one, letting a model reproduce biased outcomes indirectly.\n- **Disparate impact** - when a model's outcomes disproportionately disadvantage a particular demographic group, whether or not it was intended.\n"}]}, "Deployment, monitoring & drift": {"subtopics": [{"name": "Getting a model into production", "md": "\nOnce a model is trained and validated, it needs to actually run in production to be useful. **Batch scoring** runs the model periodically (e.g. nightly) against a stored batch of data, writing predictions somewhere for later use - fine when predictions don't need to be instant. **Real-time (online) scoring** computes a prediction on demand, the moment it's needed (e.g. as a transaction is happening).\n\nA major risk during this transition is **training/serving skew**: a feature getting computed differently (or from different underlying data) in the live production pipeline than it was during model training. Even a subtly different definition of the same feature name means the live model is seeing inputs it was never actually validated against.\n\n## Key terms\n- **Batch scoring** - running a model periodically against a stored batch of data rather than instantly on demand.\n- **Real-time (online) scoring** - computing a model's prediction on demand, at the moment it's needed.\n- **Training/serving skew** - a mismatch between how a feature is computed in production versus how it was computed during training.\n"}, {"name": "Data drift vs. concept drift", "md": "\nA model can degrade over time even if nothing about the model itself changes, because the world it's making predictions about keeps changing. Two distinct phenomena cause this:\n\n**Data drift** (or feature drift) is when the distribution of the input features themselves shifts over time - for a churn model, this might be a change in the typical customer's tenure or transaction frequency, perhaps due to a new marketing campaign attracting a different kind of customer.\n\n**Concept drift** is when the underlying *relationship* between the features and the target changes, even if the features' distribution looks the same - for a churn model, this might be customers with short tenure suddenly becoming much more loyal than they used to be (perhaps due to a new onboarding program), meaning \"short tenure\" no longer predicts churn the way it once did.\n\n## Key terms\n- **Data drift (feature drift)** - a change over time in the distribution of a model's input features.\n- **Concept drift** - a change over time in the underlying relationship between features and the target variable.\n"}, {"name": "Monitoring a deployed model", "md": "\nMonitoring a deployed model means tracking more than just \"is it still running.\" At minimum: track the **distribution of input features** over time (to catch data drift), and track the **distribution of the model's predicted scores** over time (a shift here is often an early warning sign, visible even before drift shows up anywhere else).\n\nThe trickiest part is **label latency**: real accuracy metrics (precision, recall, AUC) require the true outcome, which for something like churn might not be known for weeks or months after a prediction is made. Until then, feature and prediction-distribution monitoring is what you have; once real labels do arrive, recompute actual performance metrics on the fresh labeled data, compare against the original validation numbers, and use significant degradation as a trigger to investigate or retrain.\n\n## Key terms\n- **Label latency** - the delay between when a prediction is made and when the true outcome (label) needed to measure its accuracy becomes known.\n- **Retraining trigger** - a threshold of measured performance degradation (or drift) that prompts retraining the model on more recent data.\n"}]}, "End-to-end applied case study": {"subtopics": [{"name": "Framing the business problem", "md": "\nPayPal's Consumer Portfolio Growth team wants to reduce chargebacks (customers disputing a transaction with their bank) by proactively identifying transactions at high risk of being disputed, so the team can intervene (e.g. extra verification) before a dispute happens.\n\nFraming this well means applying the same discipline from the very first topic: define the target variable precisely (\"this transaction is disputed within 90 days of the charge date\" - not just \"risky\"), identify the population and grain (one row per transaction, not per customer), and check every candidate feature for whether it's genuinely known at the moment of the transaction itself - a feature like \"was this transaction later refunded\" would be leakage, since it's only known well after the fact.\n\n## Key terms\n- **Grain** - what a single row of your training data represents (here, one transaction, not one customer).\n"}, {"name": "Choosing features, a model, and a metric", "md": "\nSuppose only 0.8% of transactions in the historical data were actually disputed - a heavily imbalanced target. That imbalance should directly inform two choices: the **evaluation metric** (accuracy would be meaningless here - a model predicting \"never disputed\" would already be 99.2% accurate; precision, recall, and AUC are the metrics that actually matter, with the precision/recall tradeoff decided by the real cost of a false positive - an unnecessary extra verification step - versus a false negative - a missed dispute), and the **training approach** (class weighting or resampling, so the model isn't trained on a signal so dominated by the majority class that it never learns the rare pattern).\n\nFor the model family itself, this is structured, tabular transaction data - exactly the setting where a gradient-boosted tree ensemble is usually the strongest reasonable default, well ahead of a neural network, which would need far more data and offer far less interpretability for a decision that may need to be explained.\n\n## Key terms\n- **Evaluation metric selection** - choosing which metric to optimize and report based on the actual class balance and business cost tradeoffs, not by default.\n"}, {"name": "From validation to production judgment", "md": "\nBefore shipping, validate with proper discipline: hyperparameters tuned via cross-validation on the training data only, a single honest read from the untouched test set at the very end, and a sanity check on feature importance - if something surprising and potentially proxy-like shows up (say, a feature correlated with geography or demographics), investigate it before shipping, not after.\n\nAfter shipping, this is a case where real labels (confirmed disputes) arrive with real delay, so in the interim, monitor the distribution of input features and of the model's predicted risk scores for drift, and watch for training/serving skew between the offline features used to validate the model and the live features computed at transaction time. Once confirmed-dispute labels do arrive for a given cohort of transactions, recompute precision/recall/AUC on that fresh data and compare against the original validation numbers, using meaningful degradation as the trigger to investigate or retrain.\n"}]}};

const QUESTIONS = [{"topic": "ML workflow & problem framing", "subtopic": "Supervised vs. unsupervised learning", "diff": "easy", "type": "mc", "ask": "Which of these is a supervised learning problem?", "hint": "Supervised means you have a labeled outcome for past examples.", "bonus": false, "options": ["Grouping customers into behavioral segments with no predefined groups", "Predicting which customers will churn next month, using past customers where you know who actually churned", "Finding which transactions look unusual compared to the rest, with no examples of confirmed fraud", "Reducing a large set of correlated features down to a handful of components"], "correctIndex": 1, "explanation": "Churn prediction has a known label for past customers (did they churn or not) - that's exactly what makes it supervised. The others are all unsupervised: no predefined groups, no confirmed fraud labels, and no target variable at all.", "id": 0}, {"topic": "ML workflow & problem framing", "subtopic": "Framing the problem & avoiding data leakage", "diff": "medium", "type": "written", "ask": "Product asks you to help reduce customer churn. Walk through, in plain terms, how you'd frame this as a supervised learning problem - what's the target variable, what would a training example look like, and what's the very first thing you'd check before building anything?", "hint": "Define the target variable precisely before anything else, then think about what data leakage would look like here.", "bonus": false, "modelAnswer": "The target variable needs a precise, unambiguous definition - not \"will churn\" but something like \"makes zero transactions in the 60 days following a given reference date,\" with the reference date and window explicitly agreed with the business. A training example would be one row per customer as of some past reference date, with their features as of that date (tenure, recent activity, product usage, support tickets) and the label of whether they actually met the churn definition in the window that followed. Before building anything, the first thing to check is whether every feature you'd want to use was genuinely available and known AT that reference date - not information that only became known later, which would leak future information into the model and make it look far better in testing than it will ever perform in production.", "id": 1}, {"topic": "ML workflow & problem framing", "subtopic": "Choosing model complexity for the data you have", "diff": "hard", "type": "written", "ask": "Your manager suggests jumping straight to a neural network for a churn model with 3,000 labeled examples and 12 features. How would you respond, and why?", "hint": "Think about data size, interpretability, and what actually tends to win on small tabular datasets.", "bonus": false, "modelAnswer": "I'd push back, respectfully, and start with a simpler model first - logistic regression or a gradient-boosted tree - before reaching for a neural network. Neural networks typically need far more data than 3,000 rows to learn reliably; with only 12 features and a few thousand examples, a simpler model will very likely match or beat a neural network's accuracy while being dramatically faster to train, easier to debug, and easier to explain to stakeholders who will ask why the model flagged a given customer. I'd frame it as: let's establish a strong, interpretable baseline first, measure it properly on a held-out set, and only reach for something more complex like a neural network if there's a clear, measured gap the simpler model isn't closing - which, at this data size, would be a genuine surprise.", "id": 2}, {"id": 3, "topic": "ML workflow & problem framing", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain the distinction between supervised learning (labeled historical outcomes, split into classification for categorical targets and regression for continuous ones) and unsupervised learning (no labels, finding structure like clustering). It should cover the end-to-end workflow order - framing the business problem, defining a precise target variable, engineering features, splitting into train/validation/test, then only later deploying and monitoring - and specifically explain data leakage (a feature that wouldn't genuinely be available at prediction time) as the most common framing mistake. It should mention matching model complexity to the data volume and interpretability needs actually available, rather than defaulting to the most sophisticated option."}, {"topic": "Bias-variance tradeoff & regularization", "subtopic": "Diagnosing bias vs. variance", "diff": "easy", "type": "mc", "ask": "A model has 98% accuracy on training data and 61% accuracy on validation data. This is a sign of:", "hint": "Big gap between training and validation performance points to one specific failure mode.", "bonus": false, "options": ["High bias (underfitting)", "High variance (overfitting)", "A well-calibrated model", "Data leakage in the validation set"], "correctIndex": 1, "explanation": "A large gap between excellent training performance and much worse validation performance is the textbook signature of high variance / overfitting - the model has essentially memorized the training data rather than learning a pattern that generalizes.", "id": 4}, {"topic": "Bias-variance tradeoff & regularization", "subtopic": "Bias vs. variance", "diff": "medium", "type": "written", "ask": "Explain the bias-variance tradeoff to a product manager who has never heard the term, using a concrete example from customer churn prediction.", "hint": "Use a plain-language analogy rather than the formal definitions.", "bonus": false, "modelAnswer": "Imagine two ways of predicting churn: a very simple rule like \"anyone who hasn't logged in for 30 days will churn,\" versus a very complicated model that has essentially memorized the exact history of every customer in our training data. The simple rule is too rigid - it ignores lots of relevant detail, so it makes the same kinds of mistakes over and over. That's high bias. The overly complicated model fits our specific past customers extremely well, but it's so tuned to their exact quirks that it falls apart on new customers it hasn't seen before. That's high variance. The goal is something in between: a model flexible enough to capture the real patterns in customer behavior, but not so flexible that it starts fitting random noise specific to the customers we happened to train on.", "id": 5}, {"topic": "Bias-variance tradeoff & regularization", "subtopic": "Regularization: Ridge & Lasso", "diff": "hard", "type": "written", "ask": "You're told a churn model has both low training accuracy AND low validation accuracy. Is this a bias or variance problem, and what would you actually try to fix it? Then, a colleague suggests 'just collect more training data' - would that help here? Why or why not?", "hint": "Both being bad (not just validation) points to a specific one of the two problems - and to a specific direction to move regularization in.", "bonus": false, "modelAnswer": "Both training and validation performance being poor together is the signature of high bias, not high variance - the model is too simple or missing the right signal to fit even the data it's trained on, let alone new data. To actually fix it, I'd add more informative features, consider a more flexible model class (a gradient-boosted tree instead of plain logistic regression, for instance), or reduce regularization strength if it's currently too aggressive. Collecting more training data would not meaningfully help here - more data helps a model that's overfitting noise in a small sample (a variance problem), but if the model is fundamentally too simple or missing the right features to capture the pattern, more rows of the same limited information just gives it more data to be equally wrong about.", "id": 6}, {"id": 7, "topic": "Bias-variance tradeoff & regularization", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should define bias (error from a model too simple to capture the real pattern, underfitting) and variance (error from a model too sensitive to its specific training sample, overfitting), and explain the diagnostic: comparing training vs. validation performance, where poor performance on both signals bias and a large gap between excellent training and much worse validation performance signals variance. It should cover regularization (Ridge shrinking all coefficients smoothly, Lasso capable of zeroing some out entirely) as the main lever for reducing variance, and explicitly note that more training data helps variance but does little for bias."}, {"topic": "Classification evaluation metrics", "subtopic": "Confusion matrix, precision & recall", "diff": "easy", "type": "written", "ask": "Using the confusion matrix terms TP/FP/FN/TN, explain in your own words the difference between precision and recall.", "hint": "Precision is about the positives you predicted; recall is about the positives that actually existed.", "bonus": false, "modelAnswer": "Precision asks: of everyone I predicted as positive, what fraction actually were positive? It's TP divided by (TP + FP), and it's about how much you trust a positive prediction. Recall asks a different question: of everyone who was actually positive, what fraction did I successfully catch? It's TP divided by (TP + FN), and it's about how complete your coverage of the real positives is. A model can have high precision but low recall (very confident, but misses a lot of real cases), or the reverse (catches almost everything, but with a lot of false alarms) - which one matters more depends entirely on the cost of a false positive versus a false negative in the specific business context.", "id": 8}, {"topic": "Classification evaluation metrics", "subtopic": "Computing metrics from real predictions", "diff": "medium", "type": "pycalc", "ask": "Using the `predictions` DataFrame (repeat_payment is the actual outcome, pred_score is the model's predicted probability), compute the confusion matrix and precision/recall/F1 at a 0.5 threshold. Return one dict with all seven values.", "hint": "Turn pred_score into a 0/1 label at the 0.5 cutoff first, then compare against repeat_payment with boolean masks to get TP/FP/FN/TN, and derive precision/recall/F1 from those.", "bonus": false, "prompt": "Return result as a dict: {'TP':int, 'FP':int, 'FN':int, 'TN':int, 'precision':float, 'recall':float, 'f1':float}, the floats rounded to 3 decimals.", "ordered": false, "solution": "pred_label = (predictions['pred_score'] >= 0.5).astype(int)\ntp = int(((pred_label==1) & (predictions['repeat_payment']==1)).sum())\nfp = int(((pred_label==1) & (predictions['repeat_payment']==0)).sum())\nfn = int(((pred_label==0) & (predictions['repeat_payment']==1)).sum())\ntn = int(((pred_label==0) & (predictions['repeat_payment']==0)).sum())\nprecision = round(tp/(tp+fp), 3)\nrecall = round(tp/(tp+fn), 3)\nf1 = round(2*precision*recall/(precision+recall), 3)\nresult = {'TP': tp, 'FP': fp, 'FN': fn, 'TN': tn, 'precision': float(precision), 'recall': float(recall), 'f1': float(f1)}", "id": 9}, {"topic": "Classification evaluation metrics", "subtopic": "AUC & the rank-sum method", "diff": "hard", "type": "pycalc", "ask": "Compute the model's AUC using the rank-sum method taught in the lesson - no sklearn, just pandas/numpy/scipy. Round to 3 decimals.", "hint": "Rank every score with scipy.stats.rankdata, sum the ranks belonging to the positive class, then apply the rank-sum AUC formula from the lesson.", "bonus": false, "prompt": "Return result as a float rounded to 3 decimals.", "ordered": false, "solution": "from scipy.stats import rankdata\nranks = rankdata(predictions['pred_score'])\nn_pos = int((predictions['repeat_payment']==1).sum())\nn_neg = int((predictions['repeat_payment']==0).sum())\nrank_sum_pos = ranks[predictions['repeat_payment']==1].sum()\nauc = (rank_sum_pos - n_pos*(n_pos+1)/2) / (n_pos*n_neg)\nresult = round(float(auc), 3)", "id": 10}, {"id": 11, "topic": "Classification evaluation metrics", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should define the confusion matrix (TP/FP/FN/TN) and derive precision (TP/(TP+FP), trustworthiness of a positive call) and recall (TP/(TP+FN), completeness of catching real positives) from it, along with F1 as their harmonic mean. It should explain why accuracy is misleading on imbalanced data, and describe AUC as a threshold-independent metric - the probability a random positive example outscores a random negative one - distinct from precision/recall, which depend on a specific chosen threshold."}, {"topic": "Tree-based models", "subtopic": "Decision trees", "diff": "easy", "type": "mc", "ask": "Why does a single, unconstrained decision tree tend to overfit the training data?", "hint": "Think about how deep a tree is allowed to grow and what that lets it do to individual training rows.", "bonus": false, "options": ["It can keep splitting until each leaf is tailored to a tiny handful of specific training rows, memorizing quirks rather than general patterns", "It has too few parameters to capture any real pattern", "It always ignores the majority of the available features", "It can only make one split, so it never learns enough"], "correctIndex": 0, "explanation": "Left unconstrained, a decision tree keeps splitting the data to maximize purity in each resulting group, which lets it grow arbitrarily deep - carving out an ever-more-specific rule for smaller and smaller groups of training rows until it's essentially memorizing noise rather than a generalizable pattern.", "id": 12}, {"topic": "Tree-based models", "subtopic": "Random forests & bagging", "diff": "medium", "type": "mc", "ask": "What's the main reason a random forest tends to generalize better than a single deep decision tree?", "hint": "Think about what averaging many trees, each trained on a random slice, does to their errors.", "bonus": false, "options": ["It uses a completely different splitting rule than a single tree", "Averaging many trees, each trained on a random subset of rows and features, cancels out the individual trees' overfitting", "It always uses fewer features than a single tree, which prevents overfitting by design", "Random forests don't actually use decision trees internally"], "correctIndex": 1, "explanation": "Bagging is the key idea: each individual tree still overfits its own random slice of the data, but since those errors aren't correlated across trees, averaging (or majority-voting) their predictions cancels much of that noise out - which is what makes the forest more stable than any single tree.", "id": 13}, {"topic": "Tree-based models", "subtopic": "Gradient boosting", "diff": "hard", "type": "written", "ask": "A colleague proposes gradient boosting over random forest for a new fraud-detection model, citing better accuracy. What tradeoff should you flag before agreeing?", "hint": "Think about tuning sensitivity, training speed, and overfitting risk between the two.", "bonus": false, "modelAnswer": "Gradient boosting often does edge out random forest on tabular data like this, but it comes with real tradeoffs worth flagging before committing to it. It's more sensitive to hyperparameters - learning rate, tree depth, number of boosting rounds - and if those aren't tuned carefully with proper cross-validation, it can overfit more easily than a random forest, which is fairly robust even with default settings. It's also slower to train, since each tree in the sequence depends on the errors of the ones before it and can't be built in parallel the way a random forest's independent trees can - worth considering if this model needs to be retrained frequently as fraud patterns shift. I'd suggest building both, tuning each properly, and comparing on a proper held-out set before deciding, rather than assuming gradient boosting's typical edge holds for this specific dataset.", "id": 14}, {"id": 15, "topic": "Tree-based models", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain how a single decision tree splits data to maximize purity at each step, and why an unconstrained tree tends to overfit (memorizing tiny, specific groups of training rows). It should explain bagging - random forests training many trees independently on random subsets of rows and features, then averaging - as a variance-reduction technique, and contrast this with gradient boosting, which builds trees sequentially, each correcting the errors of the ones before it, generally more accurate but more hyperparameter-sensitive and slower to train since it can't parallelize across trees."}, {"topic": "Linear & logistic regression", "subtopic": "Linear regression basics", "diff": "easy", "type": "mc", "ask": "A linear regression predicting monthly spend has a coefficient of 2.5 on 'tenure_months'. What does that mean?", "hint": "The coefficient describes the change in the predicted outcome per unit change in that feature, holding everything else fixed.", "bonus": false, "options": ["Holding other features constant, each additional month of tenure is associated with a $2.50 increase in predicted spend", "Customers with 2.5 months of tenure spend the most", "Tenure explains 2.5% of the variation in spend", "The model is 2.5 times more accurate when tenure is included"], "correctIndex": 0, "explanation": "A linear regression coefficient describes the change in the predicted outcome for a one-unit increase in that feature, holding all other features constant - here, each extra month of tenure is associated with a $2.50 increase in predicted spend.", "id": 16}, {"topic": "Linear & logistic regression", "subtopic": "From linear to logistic regression", "diff": "medium", "type": "written", "ask": "Explain why you can't just use plain linear regression to predict whether a customer will make a repeat payment (a yes/no outcome), and what logistic regression does differently.", "hint": "Think about what a linear regression's raw output range looks like, versus what a probability needs to be.", "bonus": false, "modelAnswer": "Plain linear regression's output is unbounded - it can predict any number, including values below 0 or above 1, which makes no sense as a probability of a yes/no outcome. Logistic regression fixes this by passing that same weighted sum of features through the sigmoid function, which squashes any real number into the range (0, 1). That squashed value can then be legitimately interpreted as a probability, and a threshold (commonly 0.5) converts it into an actual yes/no prediction - which is exactly the mechanism behind a model's predicted probability score.", "id": 17}, {"topic": "Linear & logistic regression", "subtopic": "Interpreting coefficients & log loss", "diff": "hard", "type": "pycalc", "ask": "Using the `predictions` DataFrame (repeat_payment is the actual outcome, pred_score is the model's predicted probability), compute the average log loss across all 200 predictions.", "hint": "Log loss for one row is -(y*log(p) + (1-y)*log(1-p)); average that across every row.", "bonus": false, "prompt": "Return result as a float rounded to 3 decimals.", "ordered": false, "solution": "y = predictions['repeat_payment']\np = predictions['pred_score']\nper_row = -(y*np.log(p) + (1-y)*np.log(1-p))\nresult = round(float(per_row.mean()), 3)", "id": 18}, {"id": 19, "topic": "Linear & logistic regression", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain linear regression as predicting a continuous value via a weighted sum of features plus an intercept, trained by minimizing squared error, with each coefficient describing an association holding other features constant. It should explain why linear regression breaks for a binary target (unbounded output), and how logistic regression fixes this by passing the weighted sum through the sigmoid function to produce a valid probability, trained by minimizing log loss rather than squared error specifically because log loss penalizes confident wrong predictions much more heavily."}, {"topic": "Neural network fundamentals", "subtopic": "Neurons, layers & the forward pass", "diff": "easy", "type": "mc", "ask": "What does a single neuron compute?", "hint": "Think about the two-step operation every neuron performs.", "bonus": false, "options": ["A weighted sum of its inputs plus a bias, passed through an activation function", "The average of all the inputs it receives", "A random number used to initialize the network", "The final prediction for the entire network, regardless of which layer it's in"], "correctIndex": 0, "explanation": "Every neuron performs the same two-step computation: a weighted sum of its inputs plus a bias, then an activation function applied to that sum. Stacking many of these across layers is what makes a full network.", "id": 20}, {"topic": "Neural network fundamentals", "subtopic": "Why non-linear activation functions matter", "diff": "medium", "type": "written", "ask": "Why do neural networks need non-linear activation functions? What would happen if every layer used a purely linear activation?", "hint": "Think about what happens mathematically when you stack multiple purely linear transformations on top of each other.", "bonus": false, "modelAnswer": "Stacking linear layers without any non-linearity collapses mathematically into a single linear transformation, no matter how many layers you stack - the composition of linear functions is still just a linear function. That means a network built entirely from linear activations could only ever learn linear relationships between inputs and output, giving it the exact same expressive power as a single linear (or logistic) regression, regardless of how deep it is. Non-linear activation functions like ReLU or sigmoid are what let each additional layer actually add new modeling power, letting the network learn curved, complex relationships that a linear model fundamentally cannot represent.", "id": 21}, {"topic": "Neural network fundamentals", "subtopic": "Training: loss and gradient descent", "diff": "hard", "type": "pycalc", "ask": "A tiny one-neuron network has weights w1=0.4, w2=-0.6, bias=0.1, and a sigmoid activation. Compute its output for inputs x1=1.5, x2=2.0.", "hint": "Compute z = w1*x1 + w2*x2 + bias, then apply the sigmoid function 1/(1+e^-z) to z.", "bonus": false, "prompt": "Return result as a float rounded to 4 decimals.", "ordered": false, "solution": "w1, w2, bias = 0.4, -0.6, 0.1\nx1, x2 = 1.5, 2.0\nz = w1*x1 + w2*x2 + bias\noutput = 1 / (1 + np.exp(-z))\nresult = round(float(output), 4)", "id": 22}, {"id": 23, "topic": "Neural network fundamentals", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain that a neuron computes a weighted sum of inputs plus a bias, then applies an activation function, and that networks stack many neurons into layers (input, hidden, output), with a forward pass computing a prediction layer by layer. It should explain why activation functions must be non-linear - stacking purely linear layers collapses mathematically into one linear transformation, no matter how many layers - and cover gradient descent (nudging weights to reduce a loss function) and backpropagation (the algorithm that efficiently computes every weight's gradient) as the training mechanism."}, {"topic": "Feature engineering & imbalanced data", "subtopic": "What makes a good feature", "diff": "easy", "type": "mc", "ask": "Which of these is the best example of a well-engineered feature, rather than raw data handed straight to a model?", "hint": "A good feature is informative and usable, not just a raw underlying value.", "bonus": false, "options": ["The customer's raw account-creation timestamp", "'Days since last transaction', derived from a raw timestamp column", "The customer's internal database row ID", "An unencoded text column containing the customer's country name"], "correctIndex": 1, "explanation": "'Days since last transaction' is a constructed, informative feature derived from raw data - exactly what feature engineering means. A raw timestamp, an internal ID, and an unencoded text column are all raw or unusable forms that would need further engineering before a model could use them well.", "id": 24}, {"topic": "Feature engineering & imbalanced data", "subtopic": "Why imbalanced data is a problem", "diff": "medium", "type": "written", "ask": "Explain why a severely imbalanced target variable (e.g. a 1.5% fraud rate) can cause a model to perform poorly even though its overall accuracy looks high, and why accuracy is the wrong metric to trust here.", "hint": "Think about both the misleading metric problem and what imbalance does to training itself.", "bonus": false, "modelAnswer": "With a 1.5% fraud rate, a model that predicts \"not fraud\" for every single transaction would already be 98.5% accurate while catching zero actual fraud - accuracy alone can't tell the difference between a genuinely strong model and one that's just exploiting the class imbalance. The imbalance also affects training itself, not just the reported metric: since the vast majority of training examples belong to the majority class, the loss function's overall value is dominated by getting the majority class right, giving the model very little signal or incentive to actually learn the rarer, minority-class pattern. That's why metrics like precision, recall, and F1 - which look specifically at how the minority (positive) class is handled - are the ones to trust here instead of overall accuracy.", "id": 25}, {"topic": "Feature engineering & imbalanced data", "subtopic": "Handling imbalance: resampling & class weights", "diff": "hard", "type": "written", "ask": "Your team is building a fraud model where only 1.5% of transactions are fraudulent. A colleague suggests undersampling the majority class so the training set is roughly 50/50 before training. What's the benefit of doing this, and what's the critical rule about your validation and test sets that must NOT change?", "hint": "Think about what the training set needs versus what the evaluation sets need to reflect.", "bonus": false, "modelAnswer": "The benefit of undersampling the majority class in training is that it prevents the model from trivially learning to predict \"not fraud\" for everyone and effectively ignoring the rare class - with a more balanced training set, the loss function gives real weight to getting the minority class right, so the model actually has to learn what distinguishes it. The critical rule is that the validation and test sets must NOT be rebalanced - they need to be left in their original, real-world class proportions, because they exist to estimate how the model will actually perform in production, where fraud really is rare. Evaluating against an artificially balanced validation or test set would give a misleading performance estimate that doesn't reflect the true operating conditions the model will face once deployed.", "id": 26}, {"id": 27, "topic": "Feature engineering & imbalanced data", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain feature engineering as constructing informative, leakage-free, model-usable inputs from raw data (e.g. deriving 'days since last transaction' rather than using a raw timestamp), including encoding categorical variables into numeric form. It should explain why imbalanced data breaks accuracy as a metric and also distorts training itself (the majority class dominates the aggregate loss), and cover the fixes - undersampling, oversampling, and class weighting - along with the critical rule that validation and test sets must keep their original, real-world class proportions."}, {"topic": "Regression evaluation metrics", "subtopic": "MAE & RMSE", "diff": "easy", "type": "mc", "ask": "Two models have the same MAE, but Model A has a much higher RMSE than Model B. What does that tell you?", "hint": "Think about what RMSE does to large individual errors compared to MAE.", "bonus": false, "options": ["Model A has some especially large individual errors that Model B doesn't, even though their average absolute error is the same", "Model A is simply less accurate overall than Model B", "The two models must be predicting different target variables", "RMSE and MAE should always be equal, so this can't happen"], "correctIndex": 0, "explanation": "Since RMSE squares each error before averaging, it's much more sensitive to a few large individual errors than MAE, which treats every error proportionally to its size. Two models can share the same average absolute error while one of them has some much larger individual misses driving up its RMSE.", "id": 28}, {"topic": "Regression evaluation metrics", "subtopic": "R-squared (coefficient of determination)", "diff": "medium", "type": "written", "ask": "Explain what an R-squared of 0.65 means to a stakeholder, in plain language, for a model predicting next month's customer spend.", "hint": "R-squared compares the model against the simplest possible baseline: always predicting the average.", "bonus": false, "modelAnswer": "An R-squared of 0.65 means the model explains about 65% of the variation in customers' actual spend, compared to the simplest possible alternative of just predicting the average spend for every customer. Put another way, using this model's predictions instead of a flat average reduces the overall prediction error variance by roughly 65%. The remaining 35% is variation in spend that the model's current features don't explain - there's still real, unexplained variability we haven't captured, which is worth flagging honestly rather than treating the model as complete.", "id": 29}, {"topic": "Regression evaluation metrics", "subtopic": "Choosing the right metric for the business", "diff": "hard", "type": "pycalc", "ask": "A model predicted refund amounts actual=[120, 85, 200, 60, 150] against predicted=[110, 95, 180, 75, 140]. Compute MAE, RMSE, and R-squared.", "hint": "Compute the errors (actual - predicted) first, then apply the MAE, RMSE, and R-squared formulas from the lesson.", "bonus": false, "prompt": "Return result as {'mae':float, 'rmse':float, 'r2':float}, each rounded to 3 decimals.", "ordered": false, "solution": "actual = np.array([120, 85, 200, 60, 150], dtype=float)\npredicted = np.array([110, 95, 180, 75, 140], dtype=float)\nerrors = actual - predicted\nmae = round(float(np.mean(np.abs(errors))), 3)\nrmse = round(float(np.sqrt(np.mean(errors**2))), 3)\nss_res = np.sum(errors**2)\nss_tot = np.sum((actual - actual.mean())**2)\nr2 = round(float(1 - ss_res/ss_tot), 3)\nresult = {'mae': mae, 'rmse': rmse, 'r2': r2}", "id": 30}, {"id": 31, "topic": "Regression evaluation metrics", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should define MAE (average absolute error, every error counted proportionally) and RMSE (penalizes large errors disproportionately due to squaring), and explain R-squared as the proportion of variance explained relative to a naive 'always predict the average' baseline, including that R-squared can go negative if a model underperforms that baseline. It should cover choosing between these based on the actual cost of errors (RMSE when big misses are especially costly, MAE for a robust, easily-explained typical error), and flag MAPE's instability near zero actual values."}, {"topic": "Cross-validation & hyperparameter tuning", "subtopic": "Why a single validation split isn't enough", "diff": "easy", "type": "mc", "ask": "Why might a single train/validation split give a misleading estimate of model performance, especially with a small dataset?", "hint": "Think about what's random about a single split, and what happens when there's less data to average that randomness out over.", "bonus": false, "options": ["Which rows happen to land in the validation set by chance can meaningfully swing the estimated performance", "A single split always overestimates performance, in every case", "Validation sets are only useful for very large datasets", "Single splits are fine and this isn't actually a real problem"], "correctIndex": 0, "explanation": "A single split's validation score depends on which specific rows randomly ended up in the validation set - with limited data, that random luck can swing the estimate meaningfully, which is exactly the problem k-fold cross-validation is designed to average away.", "id": 32}, {"topic": "Cross-validation & hyperparameter tuning", "subtopic": "K-fold cross-validation", "diff": "medium", "type": "written", "ask": "Explain how 5-fold cross-validation works, and why averaging across folds gives a more reliable performance estimate than a single train/validation split.", "hint": "Every fold gets a turn as the held-out validation set exactly once.", "bonus": false, "modelAnswer": "In 5-fold cross-validation, the training data is split into 5 roughly equal folds. The model is trained 5 separate times, each time using 4 of the folds for training and the remaining 1 fold held out for validation - and every fold gets a turn being that held-out validation set exactly once across the 5 runs. The final reported performance is the average of the metric across all 5 runs. This is more reliable than a single split because a single split's score depends heavily on which rows happened to land in validation by chance; averaging across 5 different held-out folds cancels out much of that random noise, giving a performance estimate that reflects the model's real, general behavior rather than the luck of one particular split.", "id": 33}, {"topic": "Cross-validation & hyperparameter tuning", "subtopic": "Hyperparameter tuning & the final retrain", "diff": "hard", "type": "written", "ask": "You're tuning a gradient boosting model's learning rate and tree depth using grid search with 5-fold cross-validation. A colleague suggests picking the combination that scores best on the test set instead, to save time. Why is this a bad idea, and what should you do instead?", "hint": "Think back to what happens to a test set the moment it's used to make even one modeling decision.", "bonus": false, "modelAnswer": "Picking hyperparameters based on test-set performance means the test set is now directly influencing a modeling decision - at that point it has quietly become a second validation set, and it can no longer give an honest, unbiased read on how the final model will actually perform on genuinely unseen data. Instead, all hyperparameter comparisons should be made using cross-validated performance on the training data alone: run grid search, evaluate each combination's average performance across the 5 folds, and pick the combination with the best cross-validated score. The test set should only be touched once, at the very end, purely to report the final, honest performance of the model whose hyperparameters have already been fully decided using cross-validation.", "id": 34}, {"id": 35, "topic": "Cross-validation & hyperparameter tuning", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain why a single train/validation split carries random noise (which rows land where can swing the estimate), and describe k-fold cross-validation as splitting data into k folds, training k times with a different fold held out each time, and averaging the result for a more stable estimate. It should cover using cross-validated performance (not a single split, and never the test set) to compare hyperparameter settings via grid search (exhaustive) or random search (sampled, often more efficient with many hyperparameters), followed by a final, one-time test-set evaluation of the already-chosen model."}, {"topic": "Clustering & customer segmentation", "subtopic": "Clustering as unsupervised learning", "diff": "easy", "type": "mc", "ask": "Which of the following is a clustering (unsupervised) task, rather than classification?", "hint": "Clustering has no predefined groups and no labels at all.", "bonus": false, "options": ["Predicting whether a customer will churn next month, using past customers where you know who actually churned", "Grouping customers into behavioral segments based on spend and frequency, with no predefined 'correct' set of segments", "Predicting a customer's expected monthly spend as a dollar amount", "Predicting whether a transaction is fraudulent, using past transactions with confirmed fraud labels"], "correctIndex": 1, "explanation": "Grouping customers into behavioral segments with no predefined 'correct' groups is a clustering task - there's no label to learn from, only structure to discover. The other three all have a known target variable and labeled historical examples, making them supervised tasks (classification or regression).", "id": 36}, {"topic": "Clustering & customer segmentation", "subtopic": "K-means clustering", "diff": "medium", "type": "written", "ask": "Explain how k-means assigns customers to segments, and why feature scaling matters before running it.", "hint": "Think about what k-means actually computes distance on, and what happens when features are on very different numeric scales.", "bonus": false, "modelAnswer": "K-means starts by placing k initial centroids, then assigns every customer to whichever centroid is numerically closest to them, recomputes each centroid as the average of the customers now assigned to it, and repeats this assign-then-recompute cycle until the assignments stop changing. Feature scaling matters because that 'closest centroid' assignment is based purely on numeric distance across all the features at once: if annual spend is measured in dollars (potentially in the thousands) and tenure is measured in months (maybe up to a few hundred), spend will completely dominate the distance calculation simply because of its larger numeric scale, even if tenure is just as meaningful for segmentation. Scaling every feature to a comparable range before running k-means ensures each feature actually gets to contribute to how customers are grouped, rather than the clustering being driven almost entirely by whichever feature happens to have the largest raw numbers.", "id": 37}, {"topic": "Clustering & customer segmentation", "subtopic": "Choosing k & evaluating clusters", "diff": "hard", "type": "written", "ask": "You ran k-means with k=4 and it has the lowest within-cluster sum of squares (WCSS) among k=2 through k=6 that you tried. Is that alone a good enough reason to pick k=4? What else would you check?", "hint": "Think about what WCSS does as k keeps increasing, all the way up to k equal to the number of data points.", "bonus": false, "modelAnswer": "Lowest WCSS alone is not a good enough reason, because WCSS keeps decreasing as k increases no matter what - taken to the extreme, if k equaled the number of customers, each customer would be its own cluster and WCSS would be exactly zero. So among k=2 through k=6, the largest k tried (or close to it) will tend to look best on WCSS alone, which isn't a meaningful stopping rule by itself. I'd use the elbow method properly: plot WCSS against each value of k and look for the point where adding another cluster stops giving a meaningfully large improvement, rather than just picking the numerically lowest WCSS. I'd also check the silhouette score for how well-separated the resulting clusters actually are, and most importantly, validate that the k=4 segments are genuinely actionable for the business - that they suggest meaningfully different customer treatments or strategies, since a segmentation that scores well statistically but produces segments no one can act on differently isn't actually useful.", "id": 38}, {"id": 39, "topic": "Clustering & customer segmentation", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain clustering as unsupervised - no labels, grouping by similarity/distance - and describe k-means: choosing k upfront, assigning points to the nearest centroid, recomputing centroids, and repeating until stable. It should explain why feature scaling is essential for k-means (unscaled features with larger raw ranges dominate the distance calculation), and explain why picking k by lowest WCSS alone is broken (WCSS always decreases as k increases), motivating the elbow method, silhouette score, and ultimately checking that the resulting segments are actually actionable for the business."}, {"topic": "Causal inference & experimentation", "subtopic": "Correlation vs. causation & confounders", "diff": "easy", "type": "mc", "ask": "A company notices customers who use its mobile app have higher retention than those who don't. Which of these is a plausible confounder that would make this correlation misleading as evidence the app causes retention?", "hint": "A confounder influences both the 'cause' and the outcome, without the cause actually producing the outcome.", "bonus": false, "options": ["Customers who were already more engaged and loyal before installing the app are also more likely to install it in the first place", "The app was released in the same year as a company rebrand", "Retention is measured over a 90-day window", "The app is available on both iOS and Android"], "correctIndex": 0, "explanation": "Pre-existing engagement is a classic confounder here: it plausibly drives both app adoption and retention independently, creating a correlation between app use and retention even if the app itself has no causal effect at all.", "id": 40}, {"topic": "Causal inference & experimentation", "subtopic": "A/B testing (randomized experiments)", "diff": "medium", "type": "written", "ask": "Explain why randomization in an A/B test allows you to make causal claims, when simply comparing two pre-existing groups does not.", "hint": "Think about what randomization does to every other characteristic of the two groups, not just the one you're testing.", "bonus": false, "modelAnswer": "Randomization means every subject has an equal, random chance of ending up in the treatment or control group, regardless of any of their other characteristics - engagement, tenure, spend habits, or anything else. Because of that, the treatment and control groups should be statistically similar to each other on average across every characteristic *before* the experiment even begins, including characteristics we didn't even think to measure. Comparing two pre-existing groups instead - like app users versus non-users - offers no such guarantee: those groups likely differ systematically on other factors (like prior engagement) that also affect the outcome, so any difference you observe could be driven by those pre-existing differences rather than the thing you're actually trying to test.", "id": 41}, {"topic": "Causal inference & experimentation", "subtopic": "When you can't randomize: quasi-experimental methods", "diff": "hard", "type": "written", "ask": "Marketing wants to know if a new loyalty program increased spend, but it was rolled out to all customers at once with no control group. How would you estimate its causal effect anyway, and what's the key assumption behind your approach?", "hint": "Without a true control group, you need to construct a comparison after the fact.", "bonus": false, "modelAnswer": "I'd use difference-in-differences: compare the change in spend before versus after the rollout for the customers who received the program, against the change over that same period for a comparable group of customers who didn't get it - for instance, customers in a similar but untreated market, or a synthetic comparison group built with propensity score matching on pre-rollout characteristics. Subtracting the comparison group's change from the treated group's change isolates the program's effect from any trend that both groups would have experienced anyway (seasonality, general spend growth, etc.). The key assumption behind this is parallel trends: absent the loyalty program, the treated and comparison groups would have moved similarly over time. If that assumption doesn't hold - if the treated group was already on a different trajectory - the difference-in-differences estimate would be biased.", "id": 42}, {"id": 43, "topic": "Causal inference & experimentation", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain the difference between correlation and causation, and define a confounder as a third variable that independently drives both sides of an observed correlation, making it look causal when it isn't. It should explain why randomization in an A/B test solves this - spreading every possible confounder, known or unknown, evenly across treatment and control groups - and cover difference-in-differences (comparing before/after change between treated and comparison groups, relying on a parallel-trends assumption) and propensity score matching (pairing similar likelihood-of-treatment subjects) as quasi-experimental fallbacks when randomization isn't possible."}, {"topic": "Model interpretability & common pitfalls", "subtopic": "Why interpretability matters", "diff": "easy", "type": "mc", "ask": "Why would a regulated business (e.g. credit or lending decisions) care about model interpretability, beyond just raw accuracy?", "hint": "Think about what a company might be legally or practically required to do when a decision affects a customer.", "bonus": false, "options": ["Companies are often required to explain adverse decisions to affected customers, and interpretability also helps debug and build trust in the model", "Interpretable models are always more accurate than uninterpretable ones", "Interpretability is only useful during development and has no value once a model is deployed", "It only matters for models with fewer than 10 features"], "correctIndex": 0, "explanation": "Beyond accuracy, interpretability matters because regulated businesses are often required to explain adverse decisions to customers, and being able to explain a model's behavior also helps catch bugs or spurious patterns during development and builds stakeholder trust in the model's recommendations.", "id": 44}, {"topic": "Model interpretability & common pitfalls", "subtopic": "Global vs. local interpretability", "diff": "medium", "type": "written", "ask": "Explain the difference between a global feature importance ranking and a local, per-prediction explanation, and give an example of when you'd want each.", "hint": "Global answers 'what matters overall'; local answers 'why this specific prediction.'", "bonus": false, "modelAnswer": "Global interpretability describes the model's behavior overall - typically a feature importance ranking showing which features matter most across all predictions in general. I'd use this during development, as a sanity check that the model is relying on features that make genuine business sense rather than something spurious. Local interpretability instead explains one single prediction - why the model flagged this specific customer as high-risk, for instance - which is what's actually needed if a customer disputes a decision or a regulator asks for an explanation of one particular outcome. In short: global interpretability is for validating and understanding the model as a whole, while local interpretability is for justifying or acting on any one individual prediction.", "id": 45}, {"topic": "Model interpretability & common pitfalls", "subtopic": "Common pitfalls: proxies, correlated features & sanity checks", "diff": "hard", "type": "written", "ask": "Your model's feature importance ranks 'zip code' as the second most important feature for a loan approval model. What's the first thing you should investigate, and why?", "hint": "Think about what a geographic feature might be standing in for, even if the model never sees that characteristic directly.", "bonus": false, "modelAnswer": "The first thing I'd investigate is whether zip code is acting as a proxy for a protected characteristic, most likely race, given the well-documented historical correlation between geography and demographics in many markets. Even though the model never explicitly uses race as a feature, it can still learn a very similar pattern indirectly through a correlated proxy like zip code, which is a serious fairness and compliance risk for a regulated decision like loan approval. I'd check the correlation between zip code and available demographic data, consider replacing or supplementing it with more directly relevant, non-proxy features (like actual credit history), and audit the model's approval outcomes across demographic groups specifically to check for disparate impact before this model goes anywhere near production.", "id": 46}, {"id": 47, "topic": "Model interpretability & common pitfalls", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should explain why interpretability matters beyond accuracy - regulatory requirements to explain adverse decisions, debugging, and stakeholder trust - and distinguish global interpretability (overall feature importance, describing the model in general) from local interpretability (explaining one specific prediction). It should cover the common pitfalls: correlated features splitting or hiding true importance, and proxy variables (like zip code standing in for race) letting a model reproduce biased outcomes indirectly even without using a protected characteristic directly, motivating a disparate-impact audit whenever a feature's importance is surprising."}, {"topic": "Deployment, monitoring & drift", "subtopic": "Getting a model into production", "diff": "easy", "type": "mc", "ask": "What is 'training/serving skew'?", "hint": "Think about what could go wrong specifically in the handoff from a training pipeline to a live production pipeline.", "bonus": false, "options": ["A feature is computed differently (or from different underlying data) in production than it was during training, so the live model sees inputs it was never validated on", "The model takes longer to make predictions in production than it did during training", "The training set was larger than the production dataset", "The model was trained on a different day of the week than it's deployed"], "correctIndex": 0, "explanation": "Training/serving skew is specifically about a mismatch in how a feature is computed or sourced between the training pipeline and the live production pipeline - even a subtly different definition of the same feature means the live model is seeing inputs it was never actually validated against.", "id": 48}, {"topic": "Deployment, monitoring & drift", "subtopic": "Data drift vs. concept drift", "diff": "medium", "type": "written", "ask": "Explain the difference between data drift and concept drift, with an example of each relevant to a churn model.", "hint": "Data drift is about the inputs changing; concept drift is about the relationship between inputs and outcome changing.", "bonus": false, "modelAnswer": "Data drift is a change over time in the distribution of the model's input features themselves - for example, a churn model might start seeing a shift in typical customer tenure or transaction frequency after a new marketing campaign starts attracting a different kind of customer than before, even though the underlying relationship between features and churn hasn't changed. Concept drift is different: it's a change in the actual relationship between the features and the target, even if the features' distribution looks the same as before. For the churn model, this might look like customers with short tenure suddenly becoming much more loyal than they used to be, perhaps because of a new onboarding program - so 'short tenure' no longer predicts churn the way it once reliably did. Both can silently degrade a model's real-world performance even though nothing about the model's own code or weights has changed - the world it's predicting about has simply moved.", "id": 49}, {"topic": "Deployment, monitoring & drift", "subtopic": "Monitoring a deployed model", "diff": "hard", "type": "written", "ask": "Three months after deploying a churn model, its business impact seems to be shrinking, but you don't have updated churn labels yet since the window hasn't closed. What would you monitor in the meantime, and what's your plan once labels are available?", "hint": "Think about what you CAN measure before real labels exist, and what to do the moment they arrive.", "bonus": false, "modelAnswer": "In the meantime, without real labels yet, I'd monitor the distribution of the model's input features over time against the original training distribution to check for data drift, and I'd also monitor the distribution of the model's predicted scores over time - a shift there is often an early warning sign, visible even before you'd otherwise notice anything is wrong. I'd also double-check for training/serving skew, since a quietly broken feature pipeline in production is a common, fixable cause of exactly this kind of unexplained degradation. Once real labels do become available, I'd recompute the model's actual performance metrics - precision, recall, AUC - on that fresh labeled data and compare them directly against the original validation numbers; if there's meaningful degradation, that's the trigger to investigate further and likely retrain the model on more recent data that reflects the customers and behavior patterns it's actually seeing now.", "id": 50}, {"id": 51, "topic": "Deployment, monitoring & drift", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should distinguish batch scoring (periodic, on stored data) from real-time scoring (on-demand, immediate), and explain training/serving skew as a feature being computed differently in production than during training, causing the live model to see inputs it was never validated against. It should distinguish data drift (the input feature distribution shifting over time) from concept drift (the relationship between features and target itself changing), and explain the monitoring approach given label latency: watching feature and predicted-score distributions in the interim, then recomputing real performance metrics once true labels eventually arrive."}, {"topic": "End-to-end applied case study", "subtopic": "Framing the business problem", "diff": "easy", "type": "written", "ask": "PayPal wants to reduce chargebacks by predicting which transactions are likely to be disputed. Define a precise target variable for this problem, and name one feature that would be data leakage if included.", "hint": "A precise target variable names the exact outcome and time window; leakage is anything only known after the outcome already happened.", "bonus": false, "modelAnswer": "A precise target variable would be something like: \"this transaction is formally disputed by the cardholder's bank within 90 days of the charge date\" - naming the exact event and a specific time window, rather than a vague notion of a 'risky' transaction. One feature that would be data leakage: whether the transaction was ever refunded, or the number of related customer support tickets about this transaction - both of these are typically only known well after the transaction happened (often only once a dispute is already underway), so they wouldn't genuinely be available at the moment a real prediction would need to be made.", "id": 52}, {"topic": "End-to-end applied case study", "subtopic": "Choosing features, a model, and a metric", "diff": "medium", "type": "written", "ask": "Given that only 0.8% of transactions in the historical data were actually disputed, what evaluation metric would you lead with, what model family would you start with, and why?", "hint": "Think about what a heavily imbalanced target rules out as a trustworthy metric, and what tends to win on structured transaction data.", "bonus": false, "modelAnswer": "With only 0.8% of transactions disputed, accuracy would be a meaningless metric - a model predicting 'never disputed' for everything would already be 99.2% accurate while catching nothing. I'd lead with precision, recall, and AUC instead, deciding the precision/recall tradeoff based on the real cost of a false positive (an unnecessary extra verification step for a legitimate transaction) versus a false negative (a missed dispute). For the model family, I'd start with a gradient-boosted tree ensemble - this is structured, tabular transaction data, exactly the setting where gradient boosting is usually the strongest reasonable default, ahead of a neural network, which would need far more data than we likely have of the rare positive class and would be harder to explain if a flagged transaction needed to be justified. I'd also make sure the training approach itself accounts for the imbalance, likely via class weighting, so the model isn't trained on a loss signal so dominated by the 99.2% majority class that it never learns the rare disputed-transaction pattern.", "id": 53}, {"topic": "End-to-end applied case study", "subtopic": "From validation to production judgment", "diff": "hard", "type": "written", "ask": "The chargeback model is validated and performs well offline. Walk through what you'd check before shipping it, and what you'd monitor afterward given that confirmed-dispute labels take up to 90 days to arrive.", "hint": "Before shipping: validation discipline and a feature-importance sanity check. After shipping: what can be monitored before labels exist, and what to do once they arrive.", "bonus": false, "modelAnswer": "Before shipping, I'd confirm the hyperparameters were tuned using cross-validation on the training data only, that the test set was touched exactly once for a final honest performance read, and I'd sanity-check the feature importance ranking - if anything surprising and potentially proxy-like shows up (a feature correlated with geography or demographics, for instance), I'd investigate that before shipping, not after. After shipping, since confirmed-dispute labels take up to 90 days to arrive, I'd monitor the distribution of input features and of the model's predicted risk scores in the meantime for signs of drift, and specifically check for training/serving skew between the offline features used during validation and the live features computed at the moment of each real transaction. Once confirmed-dispute labels do arrive for a given cohort of transactions, I'd recompute precision, recall, and AUC on that fresh labeled data and compare it directly against the original validation numbers, treating any meaningful degradation as the trigger to investigate further or retrain the model on more recent transaction data.", "id": 54}, {"id": 55, "topic": "End-to-end applied case study", "subtopic": null, "diff": "recall", "type": "written", "ask": "Recall check: in your own words, summarize everything you've learned in this topic so far - as if you were teaching it to someone hearing about it for the very first time (the Feynman technique).", "hint": "Cover the core concepts and key terms in your own words, with at least one concrete example. There's no single right answer - explain it the way you'd say it out loud to a colleague.", "bonus": false, "recall": true, "modelAnswer": "A strong summary should walk through applying the full workflow to one concrete scenario end to end: framing a precise target variable and checking for leakage first, choosing an evaluation metric and training approach shaped by the actual class balance (e.g. rejecting accuracy and addressing training-loss distortion under severe imbalance), choosing a model family suited to the data's structure and interpretability needs (e.g. gradient boosting for structured tabular data), and closing with pre-launch validation discipline (cross-validated tuning, a single honest test-set read, a feature-importance sanity check) plus a concrete post-launch monitoring plan given delayed labels."}]

let current=0;
const solved=new Set();
const flagged=new Set();
const savedAnswers={};

function topicIndices(topic){const out=[];QUESTIONS.forEach((q,i)=>{if(q.topic===topic)out.push(i);});return out;}
function topicRequiredIndices(topic){return topicIndices(topic).filter(i=>!QUESTIONS[i].bonus&&!QUESTIONS[i].recall);}
function topicDone(topic){return topicRequiredIndices(topic).filter(i=>solved.has(QUESTIONS[i].id)).length;}
function requiredCount(){return QUESTIONS.filter(q=>!q.bonus&&!q.recall).length;}
function requiredSolvedCount(){let n=0;QUESTIONS.forEach(q=>{if(!q.bonus&&!q.recall&&solved.has(q.id))n++;});return n;}

function findSubtopic(topic, subtopicName){
  const l=LESSONS[topic];
  if(!l) return null;
  return l.subtopics.find(s=>s.name===subtopicName)||null;
}

function renderLesson(topic, subtopicName){
  const s=findSubtopic(topic, subtopicName);
  if(!s) return "";
  let html=renderMarkdown(s.md);
  if(s.video) html+='<div class="video-embed"><iframe src="https://www.youtube.com/embed/'+s.video.id+'" title="'+mdEscape(s.video.title)+'" allowfullscreen loading="lazy"></iframe></div>';
  if(s.note) html+='<div class="note">'+renderMarkdown(s.note)+'</div>';
  return html;
}

function buildSidebar(){
  let html="";
  TOPICS.forEach((topic,ti)=>{
    const idxs=topicIndices(topic);
    const reqLen=topicRequiredIndices(topic).length;
    if(!idxs.length) return;
    html+='<div class="topic" data-topic="'+ti+'">';
    html+='<div class="topic-head"><span class="tname">'+(ti+1)+'. '+topic+'</span><span class="frac" id="frac-'+ti+'">'+topicDone(topic)+'/'+reqLen+'</span><span class="topic-chev">hide</span></div>';
    html+='<div class="tbar"><i id="tbar-'+ti+'" style="width:'+(reqLen?topicDone(topic)/reqLen*100:0)+'%"></i></div><div class="pad">';
    idxs.forEach(i=>{
      const q=QUESTIONS[i];
      const label=q.recall?"Recall: summarize this topic":(q.ask.slice(0,40)+(q.ask.length>40?"...":""));
      html+='<button class="qbtn'+(solved.has(q.id)?" done":"")+(q.bonus?" bonus":"")+(q.recall?" recall":"")+'" data-i="'+i+'"><span class="dot">'+(solved.has(q.id)?"✓":"")+'</span><span class="star">'+(flagged.has(q.id)?"★":"")+'</span><span class="lbl">'+label+'</span></button>';
    });
    html+='</div></div>';
  });
  return html;
}

function buildMain(){
  return '<main>'
    +'<div class="qhead" id="qhead"></div>'
    +'<div class="readystrip"><div class="rt" id="rtTitle"></div><span class="rbar"><i id="rbar"></i></span><span class="rlabel" id="rlabel"></span></div>'
    +'<div class="lesson" id="lesson"><div class="lesson-head" id="lessonHead"><span class="lh" id="lessonTitle">Lesson</span><span class="chev" id="chev">hide</span></div><div class="lesson-body" id="lessonBody"></div></div>'
    +'<div class="ask" id="ask"><span class="albl">The question</span><span class="atext" id="askText"></span></div>'
    +'<div class="promptbox collapsed" id="promptBox"><div class="prompt-head" id="promptHead"><span class="plbl">Hint</span><span class="chev" id="promptChev">show</span></div><p class="hint" id="hint"></p></div>'
    +'<div class="editor-wrap">'
      +'<div class="editor-bar" id="pycalcBar"><span id="editorLabel">answer.py</span><button class="schema-toggle" id="schemaBtn">view data</button></div>'
      +'<textarea id="sql" spellcheck="false" autocapitalize="off" autocomplete="off"></textarea>'
      +'<textarea id="writtenAnswer" style="display:none" spellcheck="true" placeholder="Type your answer here - a few sentences covering the key ideas is plenty. Talk through it the way you would out loud in the interview."></textarea>'
      +'<div id="mcOptions" class="mc-options" style="display:none"></div>'
    +'</div>'
    +'<div class="actions">'
      +'<button class="act run" id="runBtn">Run and check</button>'
      +'<button class="act run" id="checkAnswerBtn" style="display:none">Check answer</button>'
      +'<button class="act" id="solBtn">Show solution</button>'
      +'<button class="act" id="explainBtn">Explain solution</button>'
      +'<button class="act" id="explainWrongBtn" style="display:none">Explain my error</button>'
      +'<select id="explainModel" class="explain-model"><option value="sonnet">Sonnet 5</option><option value="haiku">Haiku 4.5</option></select>'
      +'<button class="act" id="resetBtn">Clear</button>'
      +'<button class="act" id="prevBtn">&larr; Previous</button><button class="act" id="nextBtn">Next &rarr;</button>'
      +'<span class="kbd">Cmd / Ctrl + Enter &middot; Shift + &larr;/&rarr;</span>'
    +'</div>'
    +'<div class="verdict" id="verdict"><span class="ic" id="vic"></span><span id="vmsg"></span></div>'
    +'<div class="stdoutbox" id="stdoutBox" style="display:none"><div class="lbl">Console output</div><pre id="stdoutText"></pre></div>'
    +'<div class="stdoutbox" id="varsBox" style="display:none"><div class="lbl">Your variables</div><div id="varsText"></div></div>'
    +'<div class="results" id="resultsBox" style="display:none"><h3>Your result</h3><div class="tablescroll" id="tableScroll"></div><div class="rowcount" id="rowCount"></div></div>'
    +'<div class="solution" id="solution"><div class="lbl" id="solutionLbl">One correct solution (there are often several)</div><pre id="solText" style="display:none"></pre><div id="solProse" style="display:none"></div></div>'
    +'<div class="explainbox" id="explainBox" style="display:none"><div class="lbl" id="explainLbl">Claude explains</div><div id="explainText"></div></div>'
    +'<div class="schema" id="schema"></div></main>';
}

function updateTopic(topic){
  const ti=TOPICS.indexOf(topic);const reqLen=topicRequiredIndices(topic).length;const done=topicDone(topic);
  const frac=document.getElementById("frac-"+ti);
  if(!frac) return;
  frac.textContent=done+"/"+reqLen;frac.className="frac"+(done===reqLen?" full":"");
  document.getElementById("tbar-"+ti).style.width=(reqLen?done/reqLen*100:0)+"%";
  if(document.getElementById("rtTitle") && QUESTIONS[current].topic===topic){
    setReadystrip(topic,done,reqLen);
  }
}
function setReadystrip(topic,done,total){
  document.getElementById("rtTitle").innerHTML=topic+"<small>Topic "+(TOPICS.indexOf(topic)+1)+" of "+TOPICS.length+"</small>";
  document.getElementById("rbar").style.width=(total?done/total*100:0)+"%";
  const lab=document.getElementById("rlabel");
  if(done===0){lab.textContent="Not started";lab.className="rlabel";}
  else if(done<total){lab.textContent="In progress "+done+"/"+total;lab.className="rlabel prep";}
  else{lab.textContent="Ready ✓";lab.className="rlabel ready";}
}
function updateProgress(){
  const done=requiredSolvedCount(),total=requiredCount();
  document.getElementById("doneCount").textContent=done;
  document.getElementById("progBar").style.width=Math.round(done/total*100)+"%";
  updateQuizGate(done,total);
}
function updateQuizGate(done,total){
  const btn=document.getElementById("quizBtn");
  if(!btn) return;
  if(done>=total){btn.classList.remove("locked");btn.removeAttribute("aria-disabled");}
  else{btn.classList.add("locked");btn.setAttribute("aria-disabled","true");}
}

function setAnswerAreaForType(type){
  document.getElementById("pycalcBar").style.display=type==="pycalc"?"flex":"none";
  document.getElementById("sql").style.display=type==="pycalc"?"block":"none";
  document.getElementById("writtenAnswer").style.display=type==="written"?"block":"none";
  document.getElementById("mcOptions").style.display=type==="mc"?"block":"none";
  document.getElementById("runBtn").style.display=type==="pycalc"?"":"none";
  document.getElementById("checkAnswerBtn").style.display=type==="written"?"":"none";
  document.getElementById("solBtn").style.display=type==="mc"?"none":"";
  document.getElementById("schemaBtn").style.display=type==="pycalc"?"":"none";
}

function renderMcOptions(q){
  const box=document.getElementById("mcOptions");
  box.innerHTML=q.options.map((opt,idx)=>
    '<button class="mc-opt" data-idx="'+idx+'">'+opt+'</button>'
  ).join("");
  box.querySelectorAll(".mc-opt").forEach(btn=>{
    btn.addEventListener("click",()=>chooseMcOption(+btn.dataset.idx));
  });
}

function chooseMcOption(idx){
  const q=QUESTIONS[current];
  const box=document.getElementById("mcOptions");
  const correct=idx===q.correctIndex;
  box.querySelectorAll(".mc-opt").forEach((btn,i)=>{
    btn.classList.remove("correct","incorrect");
    if(i===q.correctIndex && (correct || btn.dataset.revealed)) btn.classList.add("correct");
  });
  const chosenBtn=box.querySelector('.mc-opt[data-idx="'+idx+'"]');
  if(!correct) chosenBtn.classList.add("incorrect");
  else chosenBtn.classList.add("correct");
  box.querySelectorAll(".mc-opt").forEach(btn=>{btn.dataset.revealed="1";});
  const verdict=document.getElementById("verdict"),vic=document.getElementById("vic"),vmsg=document.getElementById("vmsg");
  verdict.className="verdict "+(correct?"ok":"no");
  vic.textContent=correct?"✓":"✗";
  vmsg.textContent=correct?q.explanation:"Not quite - "+q.explanation;
  savedAnswers[q.id]=String(idx);
  logAttempt(q.id,q.options[idx],correct);
  if(correct) markSolved(current);
  setExplainWrongVisible(!correct);
}

function loadQuestion(i){
  current=i;const q=QUESTIONS[i];
  document.getElementById("qtick").textContent="Q"+(i+1);
  document.getElementById("qhead").innerHTML='<button class="star-toggle" id="starToggle" type="button" aria-label="Mark to come back to">☆</button><span class="pill '+q.diff+'">'+q.diff+'</span><span class="pill">'+q.topic+'</span><span class="pill est" id="estBadge">'+estimateLabel(q.diff)+'</span><span class="qtimer" id="qtimerMain">00:00</span><span class="cleared '+(solved.has(q.id)?"show":"")+'" id="clearedStamp">cleared</span>';
  renderStar(q.id);
  document.getElementById("starToggle").addEventListener("click",()=>toggleFlag(q.id));
  startQuestionTimer(q.diff);
  const lessonCard=document.getElementById("lesson");
  if(q.recall){
    lessonCard.style.display="none";
  }else{
    lessonCard.style.display="";
    document.getElementById("lessonTitle").textContent=q.subtopic||"Lesson";
    document.getElementById("lessonBody").innerHTML=renderLesson(q.topic, q.subtopic);
  }
  document.getElementById("askText").textContent=q.ask;
  document.getElementById("promptBox").classList.add("collapsed");
  document.getElementById("promptChev").textContent="show";
  document.getElementById("hint").innerHTML="<b>Hint:</b> "+q.hint;
  setAnswerAreaForType(q.type);
  document.getElementById("verdict").className="verdict";
  document.getElementById("stdoutBox").style.display="none";
  document.getElementById("varsBox").style.display="none";
  document.getElementById("resultsBox").style.display="none";
  document.getElementById("solution").className="solution";
  document.getElementById("explainBox").style.display="none";
  setExplainWrongVisible(false);
  const solLbl=document.getElementById("solutionLbl"),solText=document.getElementById("solText"),solProse=document.getElementById("solProse");
  if(q.type==="pycalc"){
    solLbl.textContent="One correct solution (there are often several)";
    solText.style.display="block";solText.textContent=q.solution;
    solProse.style.display="none";
    document.getElementById("sql").value=savedAnswers[q.id]||"";
  }else if(q.type==="written"){
    solLbl.textContent=q.recall?"What a strong summary should cover":"Model answer";
    solText.style.display="none";
    solProse.style.display="block";solProse.innerHTML=renderMarkdown(q.modelAnswer);
    document.getElementById("writtenAnswer").value=savedAnswers[q.id]||"";
  }else{
    renderMcOptions(q);
  }
  const reqLen=topicRequiredIndices(q.topic).length;setReadystrip(q.topic,topicDone(q.topic),reqLen);
  document.querySelectorAll(".qbtn").forEach(b=>b.classList.toggle("active",+b.dataset.i===i));
  document.getElementById("prevBtn").disabled=(i===0);
  document.getElementById("nextBtn").disabled=(i===QUESTIONS.length-1);
  document.querySelector("main").scrollIntoView({behavior:"smooth",block:"start"});
  if(q.type==="pycalc") document.getElementById("sql").focus({preventScroll:true});
  else if(q.type==="written") document.getElementById("writtenAnswer").focus({preventScroll:true});
}
function goToQuestion(delta){
  const next=current+delta;
  if(next>=0 && next<QUESTIONS.length) loadQuestion(next);
}
function markSolved(i){
  const id=QUESTIONS[i].id;
  if(!solved.has(id)){
    solved.add(id);
    const btn=document.querySelector('.qbtn[data-i="'+i+'"]');
    if(btn){btn.classList.add("done");btn.querySelector(".dot").textContent="✓";}
    const st=document.getElementById("clearedStamp");if(st)st.classList.add("show");
    updateProgress();updateTopic(QUESTIONS[i].topic);
  }
}

async function doRunPycalc(){
  const q=QUESTIONS[current];const code=document.getElementById("sql").value;
  const verdict=document.getElementById("verdict"),vic=document.getElementById("vic"),vmsg=document.getElementById("vmsg"),resultsBox=document.getElementById("resultsBox");
  if(!code.trim())return;
  const runBtn=document.getElementById("runBtn");
  runBtn.disabled=true;runBtn.textContent="Running...";
  let g;
  try{
    g=await runAndGrade(code, q.solution, q.ordered);
  }finally{
    runBtn.disabled=false;runBtn.textContent="Run and check";
  }
  const stdoutBox=document.getElementById("stdoutBox");
  if(g.stdout && g.stdout.trim()){
    stdoutBox.style.display="block";
    document.getElementById("stdoutText").textContent=g.stdout;
  }else{
    stdoutBox.style.display="none";
  }
  const varsBox=document.getElementById("varsBox");
  varsBox.style.display="none";
  if(g.error){
    verdict.className="verdict no";vic.textContent="!";vmsg.textContent="Python error: "+g.error;
    resultsBox.style.display="none";
    setExplainWrongVisible(true);
    return;
  }
  if(g.no_result){
    verdict.className="verdict no";vic.textContent="?";vmsg.textContent=g.msg;
    resultsBox.style.display="none";
    setExplainWrongVisible(true);
    if(g.vars && g.vars.length){
      varsBox.style.display="block";
      document.getElementById("varsText").innerHTML=g.vars.map(v=>
        '<div style="margin-bottom:6px"><b>'+v.name+'</b> <span style="color:var(--muted)">('+v.type+')</span><br>'+v.preview+'</div>'
      ).join("");
    }
    return;
  }
  resultsBox.style.display="block";
  document.getElementById("tableScroll").innerHTML=renderPyTable(g);
  const n=g.rowcount;
  document.getElementById("rowCount").textContent=n+" row"+(n===1?"":"s")+" returned"+(n>200?" (showing first 200)":"")+(g.source==="last_expression"?" (read from the last line of your code)":"");
  if(g.ok){verdict.className="verdict ok";vic.textContent="✓";vmsg.textContent=g.msg;markSolved(current);savedAnswers[q.id]=code;}
  else{verdict.className="verdict no";vic.textContent="✗";vmsg.textContent=g.msg;}
  logAttempt(q.id,code,g.ok);
  setExplainWrongVisible(!g.ok);
}

async function doCheckWritten(){
  const q=QUESTIONS[current];
  const answer=document.getElementById("writtenAnswer").value.trim();
  if(!answer) return;
  savedAnswers[q.id]=answer;
  const btn=document.getElementById("checkAnswerBtn");
  const orig=btn.textContent;
  btn.disabled=true;btn.textContent="Checking...";
  const box=document.getElementById("explainBox"),txt=document.getElementById("explainText"),lbl=document.getElementById("explainLbl");
  lbl.textContent="Feedback on your answer";
  box.style.display="block";
  txt.innerHTML='<div class="explain-loading"><span class="spinner"></span>Reading through your answer…</div>';
  const verdict=document.getElementById("verdict"),vic=document.getElementById("vic"),vmsg=document.getElementById("vmsg");
  try{
    const payload={track:"ml",mode:"trainer",questionId:q.id,kind:"grade",ask:q.ask,solution:q.modelAnswer,studentAnswer:answer,model:getExplainModel()};
    const r=await requestExplanation(payload);
    txt.innerHTML=renderMarkdown(r.content);
    box.scrollIntoView({behavior:"smooth",block:"nearest"});
    const strong=/\*\*strong\*\*/i.test(r.content) || /^strong/i.test(r.content.replace(/[*_]/g,""));
    verdict.className="verdict "+(strong?"ok":"no");
    vic.textContent=strong?"✓":"~";
    vmsg.textContent=strong?"Graded as strong - see feedback below.":"See feedback below for what to add.";
    logAttempt(q.id,answer,strong);
    if(strong) markSolved(current);
  }catch(e){
    txt.textContent=e.message;
  }finally{
    btn.disabled=false;btn.textContent=orig;
    lbl.textContent="Claude explains";
  }
}

function doRun(){
  const q=QUESTIONS[current];
  if(q.type==="pycalc") return doRunPycalc();
  if(q.type==="written") return doCheckWritten();
}

let supabaseClient=null, currentUser=null, startIndex=0;

function initSupabase(){
  supabaseClient=window.supabase.createClient(window.__SUPABASE_URL__, window.__SUPABASE_ANON_KEY__);
}

function showSignOutBtn(){
  const btn=document.getElementById("signOutBtn");
  btn.classList.add("visible");
  btn.addEventListener("click",()=>{
    supabaseClient.auth.signOut().then(()=>window.location.reload());
  });
}

function requireAuth(){
  return supabaseClient.auth.getSession().then(({data:{session}})=>{
    if(session){currentUser=session.user;showSignOutBtn();return;}
    const gate=document.getElementById("authGate");
    gate.style.display="flex";
    return new Promise(resolve=>{
      document.getElementById("googleSignInBtn").addEventListener("click",()=>{
        supabaseClient.auth.signInWithOAuth({provider:"google",options:{redirectTo:window.location.origin}});
      });
      supabaseClient.auth.onAuthStateChange((event,session)=>{
        if(session && !currentUser){
          currentUser=session.user;
          gate.style.display="none";
          showSignOutBtn();
          resolve();
        }
      });
    });
  });
}

function hydrateProgress(){
  return supabaseClient.from("attempts").select("question_id,passed,query_text,created_at").eq("mode","trainer").eq("track","ml").order("created_at",{ascending:true})
    .then(({data,error})=>{
      if(error||!data) return;
      data.forEach(r=>{
        if(r.passed){solved.add(r.question_id);savedAnswers[r.question_id]=r.query_text;}
      });
      if(data.length) startIndex=data[data.length-1].question_id;
    });
}

function hydrateFlags(){
  return fetchFlaggedIds("ml","trainer").then(ids=>ids.forEach(id=>flagged.add(id)));
}

function toggleFlag(id){
  const on=!flagged.has(id);
  if(on) flagged.add(id); else flagged.delete(id);
  setQuestionFlag("ml","trainer",id,on);
  renderStar(id);
  const btn=document.querySelector('.qbtn[data-i="'+current+'"]');
  if(btn){
    const st=btn.querySelector(".star");
    if(st) st.textContent=on?"★":"";
  }
}

function renderStar(id){
  const btn=document.getElementById("starToggle");
  if(!btn) return;
  const on=flagged.has(id);
  btn.textContent=on?"★":"☆";
  btn.classList.toggle("on",on);
  btn.setAttribute("aria-label",on?"Marked to come back to":"Mark to come back to");
}

async function runExplain(kind){
  const q=QUESTIONS[current];
  const btn=document.getElementById(kind==="solution"?"explainBtn":"explainWrongBtn");
  const box=document.getElementById("explainBox"),lbl=document.getElementById("explainLbl");
  const txt=document.getElementById("explainText");
  const orig=btn.textContent;
  btn.disabled=true;btn.textContent="Thinking...";
  lbl.textContent="Claude explains";
  box.style.display="block";
  txt.innerHTML='<div class="explain-loading"><span class="spinner"></span>Thinking through the solution…</div>';
  try{
    const refSolution=q.type==="mc" ?
      "Correct answer: "+q.options[q.correctIndex]+". "+q.explanation :
      (q.type==="written" ? q.modelAnswer : q.solution);
    const payload={track:"ml",mode:"trainer",questionId:q.id,kind,ask:q.ask,prompt:"",solution:refSolution,model:getExplainModel()};
    if(kind==="attempt"){
      payload.userCode=q.type==="pycalc" ? document.getElementById("sql").value : (savedAnswers[q.id]||"");
    }
    const r=await requestExplanation(payload);
    txt.innerHTML=renderMarkdown(r.content);
    box.scrollIntoView({behavior:"smooth",block:"nearest"});
  }catch(e){
    txt.textContent=e.message;
  }finally{
    btn.disabled=false;btn.textContent=orig;
  }
}

function logAttempt(questionId,answerText,passed){
  if(!supabaseClient||!currentUser) return;
  supabaseClient.from("attempts").insert({question_id:questionId,query_text:answerText,passed,mode:"trainer",track:"ml"}).then(()=>{});
}

initSupabase();
initThemeToggle();
initTrainerSelect();

window.addEventListener("scroll",()=>{
  document.body.classList.toggle("scrolled",window.scrollY>30);
  syncHeaderHeight();
  setTimeout(syncHeaderHeight,200);
},{passive:true});

if(window.visualViewport){
  window.visualViewport.addEventListener("resize",()=>{
    document.body.classList.toggle("scrolled",window.scrollY>30);
    syncHeaderHeight();
  });
}

window.addEventListener("resize",syncHeaderHeight);
syncHeaderHeight();
setTimeout(syncHeaderHeight,300);

Promise.all([
  initPyodideEnv(),
  requireAuth().then(()=>Promise.all([hydrateProgress(),hydrateFlags()]))
])
.then(()=>{
  const app=document.getElementById("app");app.className="";
  app.innerHTML='<div class="wrap"><aside id="sidebar">'+buildSidebar()+'</aside>'+buildMain()+'<div class="col-resizer" id="colResizer"></div><div class="right-col" id="rightCol"></div></div>';
  document.getElementById("schema").innerHTML=buildPySchema();
  document.getElementById("totalCount").textContent=requiredCount();
  document.querySelectorAll(".qbtn").forEach(b=>b.addEventListener("click",()=>loadQuestion(+b.dataset.i)));
  document.getElementById("runBtn").addEventListener("click",doRun);
  document.getElementById("checkAnswerBtn").addEventListener("click",doRun);
  document.getElementById("explainBtn").addEventListener("click",()=>runExplain("solution"));
  document.getElementById("explainWrongBtn").addEventListener("click",()=>runExplain("attempt"));
  initExplainModelSelect();
  initShellLayout();
  initTopicCollapse("collapsedTopicsMl");
  document.getElementById("solBtn").addEventListener("click",()=>document.getElementById("solution").classList.toggle("show"));
  document.getElementById("resetBtn").addEventListener("click",()=>{
    const q=QUESTIONS[current];
    if(q.type==="pycalc"){document.getElementById("sql").value="";document.getElementById("sql").focus();}
    else if(q.type==="written"){document.getElementById("writtenAnswer").value="";document.getElementById("writtenAnswer").focus();}
  });
  document.getElementById("schemaBtn").addEventListener("click",()=>document.getElementById("schema").scrollIntoView({behavior:"smooth"}));
  document.getElementById("prevBtn").addEventListener("click",()=>goToQuestion(-1));
  document.getElementById("nextBtn").addEventListener("click",()=>goToQuestion(1));
  const lh=document.getElementById("lessonHead");
  lh.addEventListener("click",()=>{const l=document.getElementById("lesson");l.classList.toggle("collapsed");document.getElementById("chev").textContent=l.classList.contains("collapsed")?"show":"hide";});
  const ph=document.getElementById("promptHead");
  ph.addEventListener("click",()=>{const p=document.getElementById("promptBox");p.classList.toggle("collapsed");document.getElementById("promptChev").textContent=p.classList.contains("collapsed")?"show":"hide";});
  const ta=document.getElementById("sql");
  ta.addEventListener("keydown",e=>{
    if((e.metaKey||e.ctrlKey)&&e.key==="Enter"){e.preventDefault();doRun();}
    if(e.key==="Tab"){e.preventDefault();const s=ta.selectionStart,en=ta.selectionEnd;ta.value=ta.value.slice(0,s)+"    "+ta.value.slice(en);ta.selectionStart=ta.selectionEnd=s+4;}
  });
  const wa=document.getElementById("writtenAnswer");
  wa.addEventListener("keydown",e=>{
    if((e.metaKey||e.ctrlKey)&&e.key==="Enter"){e.preventDefault();doRun();}
  });
  document.addEventListener("keydown",e=>{
    if(!e.shiftKey || document.activeElement===ta || document.activeElement===wa) return;
    if(e.key==="ArrowLeft"){e.preventDefault();goToQuestion(-1);}
    if(e.key==="ArrowRight"){e.preventDefault();goToQuestion(1);}
  });
  updateProgress();loadQuestion(startIndex);
});
